// Auto-generated meditation translations

export const meditationTexts: Record<string, Record<string, string>> = {
  "breath-awareness.title": { es: 'Conciencia de la Respiración', en: 'Breath Awareness', fr: 'Conscience du Souffle', ko: '호흡 알아차림', ja: '呼吸の氣づき', zh: '呼吸觉察', it: 'Consapevolezza del Respiro', "pt-BR": 'Consciência da Respiração', pt: 'Consciência da Respiração', de: 'Atembewusstsein', ar: 'الوعي بالتنفس', nl: 'Adembewustzijn', hi: 'सांस की जागरूकता', pl: 'Świadomość Oddechu', sv: 'Medveten Andning', tr: 'Nefes Farkındalığı', "zh-TW": '呼吸覺知' },
  "breath-awareness.subtitle": { es: 'El puente entre el cuerpo y la mente', en: 'The bridge between body and mind', fr: 'Le pont entre le corps et l\'esprit', ko: '몸과 마음을 잇는 다리', ja: '身体と心を繋ぐ橋', zh: '身体与心灵之间的桥梁', it: 'Il ponte tra corpo e mente', "pt-BR": 'A ponte entre o corpo e a mente', pt: 'A ponte entre o corpo e a mente', de: 'Die Brücke zwischen Körper und Geist', ar: 'الجسر بين الجسد والعقل', nl: 'De brug tussen lichaam en geest', hi: 'शरीर और मन के बीच का सेतु', pl: 'Most między ciałem a umysłem', sv: 'Bron mellan kropp och sinne', tr: 'Beden ve zihin arasındaki köprü', "zh-TW": '身體與心靈之間的橋樑' },
  "breath-awareness.description": { es: 'Observa tu respiración natural sin modificarla. Siente el aire entrando y saliendo. Esta práctica fundamental cultiva la atención plena y te conecta con el momento presente. La respiración es el ancla que siempre está contigo.', en: 'Observe your natural breath without changing it. Feel the air entering and leaving. This fundamental practice cultivates mindfulness and connects you with the present moment. Your breath is the anchor that is always with you.', fr: 'Observez votre respiration naturelle sans la modifier. Ressentez l\'air qui entre et qui sort. Cette pratique fondamentale cultive la pleine conscience et vous connecte au moment présent. Votre respiration est l\'ancre qui est toujours avec vous.', ko: '호흡을 바꾸지 않고 자연스러운 숨을 관찰하세요. 공기가 들어오고 나가는 것을 느껴보세요. 이 근본적인 수행은 마음챙김을 기르고 현재 순간과 연결시켜 줍니다. 당신의 호흡은 항상 함께하는 닻입니다.', ja: '自然な呼吸を変えずに観察しましょう。空気が出入りするのを感じてください。この基本的な実践はマインドフルネスを育み、今この瞬間とあなたを繋げます。呼吸は常にあなたとともにあるアンカーです。', zh: '观察你的自然呼吸，不做任何改变。感受空气的进出。这一基本练习培养正念，让你与当下时刻连接。你的呼吸是永远与你同在的锚。', it: 'Osserva il tuo respiro naturale senza modificarlo. Senti l\'aria che entra e che esce. Questa pratica fondamentale coltiva la consapevolezza e ti connette con il momento presente. Il tuo respiro è l\'ancora che è sempre con te.', "pt-BR": 'Observe sua respiração natural sem modificá-la. Sinta o ar entrando e saindo. Esta prática fundamental cultiva a atenção plena e conecta você com o momento presente. Sua respiração é a âncora que está sempre com você.', pt: 'Observe a sua respiração natural sem a alterar. Sinta o ar a entrar e a sair. Esta prática fundamental cultiva a atenção plena e conecta-o com o momento presente. A sua respiração é a âncora que está sempre consigo.', de: 'Beobachte deinen natürlichen Atem, ohne ihn zu verändern. Spüre die Luft, wie sie ein- und ausströmt. Diese grundlegende Praxis kultiviert Achtsamkeit und verbindet dich mit dem gegenwärtigen Moment. Dein Atem ist der Anker, der immer bei dir ist.', ar: 'راقب تنفسك الطبيعي دون تغييره. اشعر بالهواء وهو يدخل ويخرج. هذه الممارسة الأساسية تنمي اليقظة الذهنية وتوصلك باللحظة الحاضرة. أنفاسك هي المرساة التي تكون معك دائمًا.', nl: 'Observeer je natuurlijke ademhaling zonder haar te veranderen. Voel de lucht die binnenkomt en weer vertrekt. Deze fundamentele oefening cultiveert mindfulness en verbindt je met het huidige moment. Je adem is het anker dat altijd bij je is.', hi: 'अपनी प्राकृतिक सांस को बिना बदले देखें। हवा को अंदर और बाहर आते हुए महसूस करें। यह मूलभूत अभ्यास सचेतनता विकसित करता है और आपको वर्तमान क्षण से जोड़ता है। आपकी सांस वह लंगर है जो हमेशा आपके साथ है।', pl: 'Obserwuj swój naturalny oddech bez zmieniania go. Poczuj powietrze wchodzące i wychodzące. Ta podstawowa praktyka rozwija uważność i łączy cię z chwilą obecną. Twój oddech jest kotwicą, która zawsze jest z tobą.', sv: 'Observera din naturliga andning utan att förändra den. Känn luften komma in och lämna. Denna grundläggande praktik odlar medveten närvaro och förbinder dig med nuet. Din andning är ankaret som alltid är med dig.', tr: 'Doğal nefesini değiştirmeden gözlemle. Havanın girişini ve çıkışını hisset. Bu temel uygulama farkındalığı geliştirir ve seni şimdiki ana bağlar. Nefesin her zaman seninle olan çapandır.', "zh-TW": '觀察你自然的呼吸，不要改變它。感受空氣的進出。這個基礎練習培養正念，讓你與當下連結。你的呼吸是永遠與你同在的錨。' },
  "body-scan.title": { es: 'Escáner Corporal', en: 'Body Scan', fr: 'Scanner Corporel', ko: '바디 스캔', ja: 'ボディスキャン', zh: '身体扫描', it: 'Scansione Corporea', "pt-BR": 'Escaneamento Corporal', pt: 'Varredura Corporal', de: 'Körperscan', ar: 'مسح الجسد', nl: 'Body Scan', hi: 'बॉडी स्कैन', pl: 'Skanowanie Ciała', sv: 'Kroppsskanning', tr: 'Beden Taraması', "zh-TW": '身體掃描' },
  "body-scan.subtitle": { es: 'Habita cada rincón de tu cuerpo', en: 'Inhabit every corner of your body', fr: 'Habitez chaque recoin de votre corps', ko: '몸 구석구석에 깃들다', ja: '身体の隅々に宿る', zh: '栖居身体的每一个角落', it: 'Abità ogni angolo del tuo corpo', "pt-BR": 'Habite cada canto do seu corpo', pt: 'Habite cada canto do seu corpo', de: 'Bewohne jede Ecke deines Körpers', ar: 'اسكن كل ركن من جسدك', nl: 'Bewoon elke hoek van je lichaam', hi: 'अपने शरीर के हर कोने में बसें', pl: 'Zamieszkaj każdy zakątek swojego ciała', sv: 'Bebo varje hörn av din kropp', tr: 'Bedeninin her köşesinde var ol', "zh-TW": '居住在你身體的每一個角落' },
  "body-scan.description": { es: 'Recorre tu cuerpo con atención sistemática, desde los pies hasta la coronilla. Esta práctica profundiza la conexión mente-cuerpo y libera tensiones acumuladas que ni siquiera sabías que llevabas.', en: 'Scan your body with systematic attention, from your toes to the crown of your head. This practice deepens the mind-body connection and releases accumulated tension you didn\'t even know you were carrying.', fr: 'Parcourez votre corps avec une attention systématique, de vos orteils au sommet de votre tête. Cette pratique approfondit la connexion corps-esprit et libère les tensions accumulées que vous ne saviez même pas porter.', ko: '발가락부터 정수리까지 체계적인 주의로 몸을 스캔하세요. 이 수행은 몸과 마음의 연결을 깊게 하고 당신이 짊어지고 있다는 것조차 몰랐던 긴장을 풀어줍니다.', ja: 'つま先から頭頂まで、体系的な注意で身体をスキャンします。この実践は心身の繋がりを深め、あなたが気づいていなかった蓄積された緊張を解放します。', zh: '用系统的注意力扫描你的身体，从脚趾到头顶。这一练习深化身心连接，释放你甚至不知道自己在背负的累积紧张。', it: 'Scansiona il tuo corpo con attenzione sistematica, dalle dita dei piedi alla sommità della testa. Questa pratica approfondisce la connessione mente-corpo e libera le tensioni accumulate che non sapevi nemmeno di portare.', "pt-BR": 'Escaneie seu corpo com atenção sistemática, dos dedos dos pés ao topo da cabeça. Esta prática aprofunda a conexão mente-corpo e libera tensões acumuladas que você nem sabia que estava carregando.', pt: 'Varra o seu corpo com atenção sistemática, dos dedos dos pés ao topo da cabeça. Esta prática aprofunda a conexão mente-corpo e liberta tensões acumuladas que nem sabia que carregava.', de: 'Scanne deinen Körper mit systematischer Aufmerksamkeit, von den Zehen bis zum Scheitel. Diese Praxis vertieft die Verbindung zwischen Geist und Körper und löst angesammelte Spannungen, von denen du nicht einmal wusstest, dass du sie trägst.', ar: 'امسح جسدك بانتباه منهجي، من أصابع قدميك إلى قمة رأسك. هذه الممارسة تعمق الاتصال بين العقل والجسد وتحرر التوتر المتراكم الذي لم تكن تعلم أنك تحمله.', nl: 'Scan je lichaam met systematische aandacht, van je tenen tot de kruin van je hoofd. Deze oefening verdiept de verbinding tussen lichaam en geest en laat opgebouwde spanning los waarvan je niet eens wist dat je die vasthield.', hi: 'अपने शरीर को पैर की उंगलियों से लेकर सिर के शीर्ष तक व्यवस्थित ध्यान से स्कैन करें। यह अभ्यास मन-शरीर के संबंध को गहरा करता है और संचित तनाव को मुक्त करता है जिसे आप नहीं जानते थे कि आप ले जा रहे हैं।', pl: 'Skanuj swoje ciało z systematyczną uwagą, od palców u stóp po czubek głowy. Ta praktyka pogłębia połączenie umysłu z ciałem i uwalnia nagromadzone napięcie, o którym nawet nie wiedziałeś, że nosisz.', sv: 'Skanna din kropp med systematisk uppmärksamhet, från tårna till hjässan. Denna praktik fördjupar kropp-sinne-förbindelsen och släpper ackumulerad spänning som du inte ens visste att du bar på.', tr: 'Bedenini ayak parmaklarından başının tepesine kadar sistematik bir dikkatle tara. Bu uygulama zihin-beden bağlantısını derinleştirir ve taşıdığını bile bilmediğin birikmiş gerilimleri serbest bırakır.', "zh-TW": '從腳趾到頭頂，系統性地掃描你的身體。這個練習深化身心連結，釋放你甚至不知道自己攜帶的累積緊張。' },
  "aum-chanting.title": { es: 'Canto de Aum', en: 'Aum Chanting', fr: 'Chant d\'Aum', ko: 'AUM 차팅', ja: 'AUMチャンティング', zh: 'AUM唱诵', it: 'Canto di Aum', "pt-BR": 'Canto de Aum', pt: 'Canto de Aum', de: 'Aum-Rezitation', ar: 'ترتيل أوم', nl: 'Aum Chanten', hi: 'ओम का जाप', pl: 'Śpiewanie Aum', sv: 'Aum-mantra', tr: 'Aum İlahisi', "zh-TW": 'AUM唱誦' },
  "aum-chanting.subtitle": { es: 'La vibración primordial del universo', en: 'The primordial vibration of the universe', fr: 'La vibration primordiale de l\'univers', ko: '우주의 원초적 진동', ja: '宇宙の原初の振動', zh: '宇宙的原初振动', it: 'La vibrazione primordiale dell\'universo', "pt-BR": 'A vibração primordial do universo', pt: 'A vibração primordial do universo', de: 'Die Urvibration des Universums', ar: 'الاهتزاز البدائي للكون', nl: 'De oervibratie van het universum', hi: 'ब्रह्मांड की आदिम कंपन', pl: 'Pierwotna wibracja wszechświata', sv: 'Universums urvibration', tr: 'Evrenin ilkel titreşimi', "zh-TW": '宇宙的原初振動' },
  "aum-chanting.description": { es: 'El Aum no es solo un sonido, es la vibración fundamental de la existencia. Al cantar Aum, sintonizas tu sistema con el ritmo del cosmos. Siente la vibración en tu pecho, garganta y cabeza. Deja que el sonido te lleve más allá del pensamiento.', en: 'Aum is not just a sound, it is the fundamental vibration of existence. By chanting Aum, you tune your system with the rhythm of the cosmos. Feel the vibration in your chest, throat, and head. Let the sound carry you beyond thought.', fr: 'Aum n\'est pas qu\'un son, c\'est la vibration fondamentale de l\'existence. En chantant Aum, vous accordez votre système au rythme du cosmos. Ressentez la vibration dans votre poitrine, votre gorge et votre tête. Laissez le son vous emmener au-delà de la pensée.', ko: 'AUM은 단순한 소리가 아니라 존재의 근본 진동입니다. AUM을 차팅함으로써 당신의 시스템을 우주의 리듬에 맞춥니다. 가슴, 목, 머리에서 진동을 느껴보세요. 소리가 당신을 생각 너머로 데려가게 하세요.', ja: 'AUMは単なる音ではなく、存在の根本的な振動です。AUMをチャンティングすることで、あなたのシステムを宇宙のリズムに調和させます。胸、喉、頭で振動を感じてください。音があなたを思考の彼方へ連れて行くままに任せましょう。', zh: 'AUM不仅仅是一个声音，它是存在的基本振动。通过唱诵AUM，你将自身系统与宇宙的节奏调谐。感受振动在胸腔、喉咙和头部。让声音带你超越思维。', it: 'Aum non è solo un suono, è la vibrazione fondamentale dell\'esistenza. Cantando Aum, sintonizzi il tuo sistema con il ritmo del cosmo. Senti la vibrazione nel petto, nella gola e nella testa. Lascia che il suono ti porti oltre il pensiero.', "pt-BR": 'Aum não é apenas um som, é a vibração fundamental da existência. Ao cantar Aum, você sintoniza seu sistema com o ritmo do cosmos. Sinta a vibração no peito, na garganta e na cabeça. Deixe o som te levar além do pensamento.', pt: 'Aum não é apenas um som, é a vibração fundamental da existência. Ao cantar Aum, sintoniza o seu sistema com o ritmo do cosmos. Sinta a vibração no seu peito, garganta e cabeça. Deixe o som levá-lo além do pensamento.', de: 'Aum ist nicht nur ein Klang, es ist die fundamentale Schwingung der Existenz. Indem du Aum rezitierst, stimmst du dein System auf den Rhythmus des Kosmos ein. Spüre die Vibration in deiner Brust, deinem Hals und deinem Kopf. Lass dich vom Klang jenseits der Gedanken tragen.', ar: 'أوم ليس مجرد صوت، إنه الاهتزاز الأساسي للوجود. من خلال ترتيل أوم، تضبط نظامك على إيقاع الكون. اشعر بالاهتزاز في صدرك وحلقك ورأسك. دع الصوت يحملك إلى ما وراء الفكر.', nl: 'Aum is niet zomaar een geluid, het is de fundamentele vibratie van het bestaan. Door Aum te chanten stem je je systeem af op het ritme van de kosmos. Voel de vibratie in je borst, keel en hoofd. Laat het geluid je voorbij het denken dragen.', hi: 'ओम केवल एक ध्वनि नहीं है, यह अस्तित्व का मूलभूत कंपन है। ओम का जाप करके, आप अपने सिस्टम को ब्रह्मांड की लय से जोड़ते हैं। अपनी छाती, गले और सिर में कंपन महसूस करें। ध्वनि को आपको विचार से परे ले जाने दें।', pl: 'Aum to nie tylko dźwięk, to fundamentalna wibracja istnienia. Śpiewając Aum, dostrajasz swój system do rytmu kosmosu. Poczuj wibrację w klatce piersiowej, gardle i głowie. Pozwól, by dźwięk poniósł cię poza myśl.', sv: 'Aum är inte bara ett ljud, det är existensens grundläggande vibration. Genom att sjunga Aum stämmer du in ditt system med kosmos rytm. Känn vibrationen i bröstet, halsen och huvudet. Låt ljudet bära dig bortom tanken.', tr: 'Aum yalnızca bir ses değil, varoluşun temel titreşimidir. Aum\'u söyleyerek sistemini kozmosun ritmiyle uyumlarsın. Titreşimi göğsünde, boğazında ve başında hisset. Sesin seni düşüncenin ötesine taşımasına izin ver.', "zh-TW": 'AUM不僅僅是聲音，它是存在的基本振動。通過唱誦AUM，你將你的系統與宇宙的韻律協調。感受胸口、喉嚨和頭部的振動。讓聲音帶你超越思想。' },
  "witnessing.title": { es: 'El Observador', en: 'The Witness', fr: 'Le Témoin', ko: '관찰자', ja: '観察者', zh: '观照者', it: 'Il Testimone', "pt-BR": 'A Testemunha', pt: 'A Testemunha', de: 'Der Zeuge', ar: 'الشاهد', nl: 'De Getuige', hi: 'साक्षी', pl: 'Świadek', sv: 'Vittnet', tr: 'Tanık', "zh-TW": '見證者' },
  "witnessing.subtitle": { es: 'Tú no eres tus pensamientos', en: 'You are not your thoughts', fr: 'Vous n\'êtes pas vos pensées', ko: '당신은 당신의 생각이 아닙니다', ja: 'あなたはあなたの思考ではない', zh: '你不是你的思想', it: 'Tu non sei i tuoi pensieri', "pt-BR": 'Você não é seus pensamentos', pt: 'Você não é os seus pensamentos', de: 'Du bist nicht deine Gedanken', ar: 'أنت لست أفكارك', nl: 'Je bent niet je gedachten', hi: 'आप अपने विचार नहीं हैं', pl: 'Nie jesteś swoimi myślami', sv: 'Du är inte dina tankar', tr: 'Sen düşüncelerin değilsin', "zh-TW": '你不是你的想法' },
  "witnessing.description": { es: 'Siéntate y observa tus pensamientos como nubes que pasan por el cielo. No te aferres a ninguno, no rechaces ninguno. Esta práctica crea una distancia saludable entre tu ser esencial y el constante parloteo de la mente. Descubre la paz que existe debajo del ruido mental.', en: 'Sit and observe your thoughts like clouds passing through the sky. Don\'t cling to any, don\'t reject any. This practice creates a healthy distance between your essential self and the constant chatter of the mind. Discover the peace that exists beneath the mental noise.', fr: 'Asseyez-vous et observez vos pensées comme des nuages traversant le ciel. Ne vous accrochez à aucune, n\'en rejetez aucune. Cette pratique crée une distance saine entre votre être essentiel et le bavardage constant de l\'esprit. Découvrez la paix qui existe sous le bruit mental.', ko: '앉아서 생각이 하늘을 지나가는 구름처럼 지나가는 것을 관찰하세요. 어떤 것에도 집착하지 말고, 어떤 것도 거부하지 마세요. 이 수행은 당신의 본질적 자아와 마음의 끊임없는 잡담 사이에 건강한 거리를 만듭니다. 정신적 소음 아래 존재하는 평화를 발견하세요.', ja: '座って、思考が空を通り過ぎる雲のように観察しましょう。どれにも執着せず、どれも拒絶しないでください。この実践は、あなたの本質的な自己と心の絶え間ないおしゃべりの間に健全な距離を作ります。心の雑音の下に存在する平安を発見してください。', zh: '静坐，像观察云朵飘过天空一样观察你的思想。不执着于任何一个，不排斥任何一个。这一练习在你的本质自我与头脑的持续喋喋不休之间创造健康的距离。发现存在于精神噪音之下的平静。', it: 'Siediti e osserva i tuoi pensieri come nuvole che attraversano il cielo. Non aggrapparti a nessuno, non respingere nessuno. Questa pratica crea una sana distanza tra il tuo sé essenziale e il costante chiacchiericcio della mente. Scopri la pace che esiste sotto il rumore mentale.', "pt-BR": 'Sente-se e observe seus pensamentos como nuvens passando pelo céu. Não se apegue a nenhum, não rejeite nenhum. Esta prática cria uma distância saudável entre seu eu essencial e a tagarelice constante da mente. Descubra a paz que existe abaixo do ruído mental.', pt: 'Sente-se e observe os seus pensamentos como nuvens a passar no céu. Não se agarre a nenhum, não rejeite nenhum. Esta prática cria uma distância saudável entre o seu eu essencial e a constante tagarelice da mente. Descubra a paz que existe por baixo do ruído mental.', de: 'Setze dich und beobachte deine Gedanken wie Wolken, die am Himmel vorbeiziehen. Halte an keinem fest, weise keinen zurück. Diese Praxis schafft einen gesunden Abstand zwischen deinem wesentlichen Selbst und dem ständigen Geplapper des Geistes. Entdecke den Frieden, der unter dem mentalen Lärm existiert.', ar: 'اجلس وراقب أفكارك كالغيوم التي تمر في السماء. لا تتعلق بأي منها، لا ترفض أيًا منها. هذه الممارسة تخلق مسافة صحية بين ذاتك الجوهرية والثرثرة المستمرة للعقل. اكتشف السلام الموجود تحت الضوضاء الذهنية.', nl: 'Zit en observeer je gedachten als wolken die langs de hemel trekken. Klamp je aan geen enkele vast, verwerp geen enkele. Deze oefening creëert een gezonde afstand tussen je essentiële zelf en het constante gebabbel van de geest. Ontdek de vrede die bestaat onder de mentale ruis.', hi: 'बैठें और अपने विचारों को आकाश में गुज़रते बादलों की तरह देखें। किसी से चिपकें नहीं, किसी को अस्वीकार न करें। यह अभ्यास आपके आवश्यक स्व और मन की निरंतर बकबक के बीच एक स्वस्थ दूरी बनाता है। मानसिक शोर के नीचे मौजूद शांति की खोज करें।', pl: 'Usiądź i obserwuj swoje myśli jak chmury przepływające po niebie. Nie przywiązuj się do żadnej, nie odrzucaj żadnej. Ta praktyka tworzy zdrowy dystans między twoim istotowym ja a nieustannym paplaniem umysłu. Odkryj spokój, który istnieje pod hałasem umysłu.', sv: 'Sitt och observera dina tankar som moln som passerar över himlen. Håll inte fast vid någon, avvisa inte någon. Denna praktik skapar ett sunt avstånd mellan ditt väsentliga jag och sinnets ständiga prat. Upptäck freden som finns under det mentala bruset.', tr: 'Otur ve düşüncelerini gökyüzünde geçen bulutlar gibi gözlemle. Hiçbirine tutunma, hiçbirini reddetme. Bu uygulama öz benliğin ile zihnin sürekli gevezeliği arasında sağlıklı bir mesafe oluşturur. Zihinsel gürültünün altında var olan huzuru keşfet.', "zh-TW": '坐下來，觀察你的念頭如同雲彩飄過天空。不執著於任何一個，也不拒絕任何一個。這個練習在你的本質自我與心靈不斷的嘮叨之間創造了一個健康的距離。發現存在於心靈噪音之下的平靜。' },
  "gratitude.title": { es: 'Gratitud Profunda', en: 'Deep Gratitude', fr: 'Gratitude Profonde', ko: '깊은 감사', ja: '深い感謝', zh: '深度感恩', it: 'Gratitudine Profonda', "pt-BR": 'Gratidão Profunda', pt: 'Gratidão Profunda', de: 'Tiefe Dankbarkeit', ar: 'امتنان عميق', nl: 'Diepe Dankbaarheid', hi: 'गहरी कृतज्ञता', pl: 'Głęboka Wdzięczność', sv: 'Djup Tacksamhet', tr: 'Derin Şükran', "zh-TW": '深度感恩' },
  "gratitude.subtitle": { es: 'Agradece a la existencia por todo', en: 'Thank existence for everything', fr: 'Remerciez l\'existence pour tout', ko: '모든 것에 존재에게 감사하세요', ja: 'すべてに対して存在に感謝する', zh: '感谢存在的一切', it: 'Ringrazia l\'esistenza per tutto', "pt-BR": 'Agradeça à existência por tudo', pt: 'Agradeça à existência por tudo', de: 'Danke der Existenz für alles', ar: 'اشكر الوجود على كل شيء', nl: 'Dank het bestaan voor alles', hi: 'अस्तित्व को हर चीज़ के लिए धन्यवाद दें', pl: 'Dziękuj istnieniu za wszystko', sv: 'Tacka tillvaron för allt', tr: 'Varoluşa her şey için teşekkür et', "zh-TW": '為一切感謝存在' },
  "gratitude.description": { es: 'La gratitud no es un gesto, es una forma de ser. Cuando agradeces profundamente, todo en tu vida se transforma. Esta práctica te lleva a experimentar gratitud no como concepto, sino como vivencia. Agradece a la vida, al universo, a cada célula de tu cuerpo por el milagro de la existencia.', en: 'Gratitude is not a gesture, it is a way of being. When you are deeply grateful, everything in your life transforms. This practice takes you to experience gratitude not as a concept, but as a lived experience. Thank life, the universe, every cell of your body for the miracle of existence.', fr: 'La gratitude n\'est pas un geste, c\'est une façon d\'être. Lorsque vous êtes profondément reconnaissant, tout dans votre vie se transforme. Cette pratique vous amène à expérimenter la gratitude non comme un concept, mais comme une expérience vécue. Remerciez la vie, l\'univers, chaque cellule de votre corps pour le miracle de l\'existence.', ko: '감사는 단순한 몸짓이 아니라 존재의 방식입니다. 깊이 감사할 때 당신의 삶의 모든 것이 변화합니다. 이 수행은 감사를 개념이 아닌 살아있는 경험으로 체험하게 합니다. 존재의 기적에 대해 삶, 우주, 몸의 모든 세포에 감사하세요.', ja: '感謝は単なる身振りではなく、在り方そのものです。深く感謝するとき、あなたの人生のすべてが変わります。この実践は、感謝を概念としてではなく、生きた体験として経験するよう導きます。存在の奇跡に対して、人生、宇宙、身体のすべての細胞に感謝しましょう。', zh: '感恩不是一个姿态，而是一种存在方式。当你深深感恩时，你生命中的一切都会转变。这一练习带你将感恩不仅作为一个概念，而是作为一种亲身经历去体验。感谢生命、宇宙、你身体的每一个细胞，感谢存在的奇迹。', it: 'La gratitudine non è un gesto, è un modo di essere. Quando sei profondamente grato, tutto nella tua vita si trasforma. Questa pratica ti porta a sperimentare la gratitudine non come concetto, ma come esperienza vissuta. Ringrazia la vita, l\'universo, ogni cellula del tuo corpo per il miracolo dell\'esistenza.', "pt-BR": 'A gratidão não é um gesto, é um modo de ser. Quando você é profundamente grato, tudo na sua vida se transforma. Esta prática leva você a experimentar a gratidão não como um conceito, mas como uma experiência vivida. Agradeça à vida, ao universo, a cada célula do seu corpo pelo milagre da existência.', pt: 'A gratidão não é um gesto, é uma forma de ser. Quando está profundamente grato, tudo na sua vida se transforma. Esta prática leva-o a experimentar a gratidão não como um conceito, mas como uma experiência vivida. Agradeça à vida, ao universo, a cada célula do seu corpo pelo milagre da existência.', de: 'Dankbarkeit ist keine Geste, sie ist eine Seinsweise. Wenn du tiefe Dankbarkeit empfindest, verwandelt sich alles in deinem Leben. Diese Praxis führt dich dazu, Dankbarkeit nicht als Konzept, sondern als gelebte Erfahrung zu erleben. Danke dem Leben, dem Universum, jeder Zelle deines Körpers für das Wunder der Existenz.', ar: 'الامتنان ليس مجرد إيماءة، إنه طريقة للوجود. عندما تكون ممتنًا بعمق، يتحول كل شيء في حياتك. تأخذك هذه الممارسة لتجربة الامتنان ليس كمفهوم، بل كتجربة معاشة. اشكر الحياة، الكون، كل خلية من جسدك على معجزة الوجود.', nl: 'Dankbaarheid is geen gebaar, het is een manier van zijn. Wanneer je diep dankbaar bent, verandert alles in je leven. Deze oefening laat je dankbaarheid ervaren niet als een concept, maar als een geleefde ervaring. Dank het leven, het universum, elke cel van je lichaam voor het wonder van het bestaan.', hi: 'कृतज्ञता एक इशारा नहीं है, यह होने का एक तरीका है। जब आप गहराई से आभारी होते हैं, तो आपके जीवन में सब कुछ बदल जाता है। यह अभ्यास आपको कृतज्ञता को एक अवधारणा के रूप में नहीं, बल्कि एक जीवित अनुभव के रूप में अनुभव करने ले जाता है। अस्तित्व के चमत्कार के लिए जीवन, ब्रह्मांड, अपने शरीर की हर कोशिका को धन्यवाद दें।', pl: 'Wdzięczność nie jest gestem, to sposób bycia. Kiedy jesteś głęboko wdzięczny, wszystko w twoim życiu się zmienia. Ta praktyka prowadzi cię do doświadczania wdzięczności nie jako koncepcji, ale jako przeżytego doświadczenia. Dziękuj życiu, wszechświatowi, każdej komórce swojego ciała za cud istnienia.', sv: 'Tacksamhet är inte en gest, det är ett sätt att vara. När du är djupt tacksam förvandlas allt i ditt liv. Denna praktik tar dig till att uppleva tacksamhet inte som ett begrepp, utan som en levd upplevelse. Tacka livet, universum, varje cell i din kropp för tillvarons mirakel.', tr: 'Şükran bir jest değil, bir var olma biçimidir. Derinden minnettar olduğunda hayatındaki her şey dönüşür. Bu uygulama seni şükranı bir kavram olarak değil, yaşanmış bir deneyim olarak deneyimlemeye götürür. Varoluş mucizesi için hayata, evrene, bedeninin her hücresine teşekkür et.', "zh-TW": '感恩不是一種姿態，而是一種存在方式。當你 deeply 感激時，你生活中的一切都會轉化。這個練習帶你體驗感恩，不是作為一個概念，而是作為一種活生生的經驗。為存在的奇蹟感謝生命、宇宙、你身體的每一個細胞。' },
  "inner-silence.title": { es: 'Silencio Interior', en: 'Inner Silence', fr: 'Silence Intérieur', ko: '내면의 침묵', ja: '内なる静寂', zh: '内在寂静', it: 'Silenzio Interiore', "pt-BR": 'Silêncio Interior', pt: 'Silêncio Interior', de: 'Innere Stille', ar: 'الصمت الداخلي', nl: 'Innerlijke Stilte', hi: 'आंतरिक मौन', pl: 'Wewnętrzna Cisza', sv: 'Inre Tystnad', tr: 'İç Sessizlik', "zh-TW": '內在寂靜' },
  "inner-silence.subtitle": { es: 'Más allá del sonido está la paz', en: 'Beyond sound lies peace', fr: 'Au-delà du son se trouve la paix', ko: '소리 너머에 평화가 있다', ja: '音の向こうに平安がある', zh: '声音之外是平静', it: 'Oltre il suono c\'è la pace', "pt-BR": 'Além do som está a paz', pt: 'Para além do som está a paz', de: 'Jenseits des Klangs liegt Frieden', ar: 'وراء الصوت يكمن السلام', nl: 'Voorbij geluid ligt vrede', hi: 'ध्वनि से परे शांति है', pl: 'Poza dźwiękiem leży spokój', sv: 'Bortom ljudet ligger frid', tr: 'Sesin ötesinde huzur yatar', "zh-TW": '聲音之外是平靜' },
  "inner-silence.description": { es: 'En lo más profundo de tu ser existe un espacio de silencio absoluto. Un lugar donde ningún pensamiento, emoción o sonido externo puede alcanzarte. Esta práctica te guía hacia ese santuario interior. No hay mantra, no hay instrucción — solo silencio. El silencio es el lenguaje más elevado.', en: 'In the deepest part of your being there is a space of absolute silence. A place where no thought, emotion, or external sound can reach you. This practice guides you to that inner sanctuary. No mantra, no instruction — only silence. Silence is the highest language.', fr: 'Dans la partie la plus profonde de votre être, il existe un espace de silence absolu. Un endroit où aucune pensée, émotion ou son extérieur ne peut vous atteindre. Cette pratique vous guide vers ce sanctuaire intérieur. Pas de mantra, pas d\'instruction — seulement le silence. Le silence est le langage le plus élevé.', ko: '당신 존재의 가장 깊은 곳에는 절대적인 침묵의 공간이 있습니다. 어떤 생각, 감정, 외부의 소리도 닿을 수 없는 곳입니다. 이 수행은 당신을 그 내면의 성소로 안내합니다. 만트라도, 지시도 없이 — 오직 침묵만이 있습니다. 침묵은 가장 높은 언어입니다.', ja: 'あなたの存在の最も深い部分には、絶対的な静寂の空間があります。いかなる思考、感情、外部の音も届かない場所です。この実践はあなたをその内なる聖域へ導きます。マントラも、指示もなく — ただ静寂だけがあります。静寂は最も高次の言葉です。', zh: '在你存在的最深处，有一个绝对寂静的空间。一个没有任何思想、情感或外界声音能够触及的地方。这一练习引导你进入那个内在圣殿。没有咒语，没有指令——只有寂静。寂静是最高的语言。', it: 'Nella parte più profonda del tuo essere c\'è uno spazio di silenzio assoluto. Un luogo dove nessun pensiero, emozione o suono esterno può raggiungerti. Questa pratica ti guida verso quel santuario interiore. Nessun mantra, nessuna istruzione — solo silenzio. Il silenzio è il linguaggio più elevato.', "pt-BR": 'Na parte mais profunda do seu ser existe um espaço de silêncio absoluto. Um lugar onde nenhum pensamento, emoção ou som externo pode alcançá-lo. Esta prática guia você para esse santuário interior. Sem mantra, sem instrução — apenas silêncio. O silêncio é a linguagem mais elevada.', pt: 'Na parte mais profunda do seu ser existe um espaço de silêncio absoluto. Um lugar onde nenhum pensamento, emoção ou som externo pode alcançá-lo. Esta prática guia-o para esse santuário interior. Sem mantra, sem instrução — apenas silêncio. O silêncio é a linguagem mais elevada.', de: 'Im tiefsten Teil deines Wesens gibt es einen Raum absoluter Stille. Einen Ort, an den dich kein Gedanke, keine Emotion und kein äußeres Geräusch erreichen kann. Diese Praxis führt dich zu diesem inneren Heiligtum. Kein Mantra, keine Anweisung — nur Stille. Stille ist die höchste Sprache.', ar: 'في أعمق جزء من كيانك هناك مساحة من الصمت المطلق. مكان لا يمكن لأي فكر أو عاطفة أو صوت خارجي أن يصل إليك. هذه الممارسة ترشدك إلى ذلك الملاذ الداخلي. لا ترديد، لا تعليمات — فقط صمت. الصمت هو أسمى لغة.', nl: 'In het diepste deel van je wezen is er een ruimte van absolute stilte. Een plek waar geen gedachte, emotie of extern geluid je kan bereiken. Deze oefening leidt je naar dat innerlijke heiligdom. Geen mantra, geen instructie — alleen stilte. Stilte is de hoogste taal.', hi: 'आपके अस्तित्व के सबसे गहरे हिस्से में पूर्ण मौन का एक स्थान है। एक ऐसी जगह जहां कोई विचार, भावना या बाहरी ध्वनि आप तक नहीं पहुंच सकती। यह अभ्यास आपको उस आंतरिक अभयारण्य तक ले जाता है। कोई मंत्र नहीं, कोई निर्देश नहीं — केवल मौन। मौन सबसे उच्च भाषा है।', pl: 'W najgłębszej części twojego jestestwa istnieje przestrzeń absolutnej ciszy. Miejsce, gdzie żadna myśl, emocja ani zewnętrzny dźwięk nie mogą cię dosięgnąć. Ta praktyka prowadzi cię do tego wewnętrznego sanktuarium. Żadnego mantry, żadnej instrukcji — tylko cisza. Cisza jest najwyższym językiem.', sv: 'I den djupaste delen av ditt väsen finns ett rum av absolut tystnad. En plats där ingen tanke, känsla eller yttre ljud kan nå dig. Denna praktik guidar dig till den inre helgedomen. Ingen mantra, ingen instruktion — bara tystnad. Tystnad är det högsta språket.', tr: 'Varlığının en derin yerinde mutlak sessizliğin bir alanı vardır. Hiçbir düşüncenin, duygunun veya dış sesin sana ulaşamayacağı bir yer. Bu uygulama seni o iç kutsal alana yönlendirir. Mantra yok, talimat yok — yalnızca sessizlik. Sessizlik en yüce dildir.', "zh-TW": '在你存在的最深處，有一個絕對寂靜的空間。一個沒有思想、情感或外在聲音能觸及你的地方。這個練習引導你進入那個內在聖殿。沒有咒語，沒有指示——只有寂靜。寂靜是最高層次的語言。' },
  "isha-kriya.title": { es: 'Isha Kriya', en: 'Isha Kriya', fr: 'Isha Kriya', ko: 'Isha Kriya', ja: 'Isha Kriya', zh: 'Isha Kriya', it: 'Isha Kriya', "pt-BR": 'Isha Kriya', pt: 'Isha Kriya', de: 'Isha Kriya', ar: 'إيشا كريا', nl: 'Isha Kriya', hi: 'ईशा क्रिया', pl: 'Isha Kriya', sv: 'Isha Kriya', tr: 'Isha Kriya', "zh-TW": 'Isha Kriya' },
  "isha-kriya.subtitle": { es: 'Meditación guiada de 15 minutos', en: '15-minute guided meditation', fr: 'Méditation guidée de 15 minutes', ko: '15분 안내 명상', ja: '15分のガイド付き瞑想', zh: '15分钟引导冥想', it: 'Meditazione guidata di 15 minuti', "pt-BR": 'Meditação guiada de 15 minutos', pt: 'Meditação guiada de 15 minutos', de: '15-minütige geführte Meditation', ar: 'تأمل موجه لمدة 15 دقيقة', nl: '15 minuten begeleide meditatie', hi: '15 मिनट का निर्देशित ध्यान', pl: '15-minutowa medytacja prowadzona', sv: '15-minuters guidad meditation', tr: '15 dakikalık rehberli meditasyon', "zh-TW": '15分鐘引導冥想' },
  "isha-kriya.description": { es: 'Isha Kriya es una poderosa meditación guiada de 15 minutos para la salud y el bienestar. A través de esta práctica aprenderás a usar tu respiración, pensamiento y conciencia de una manera que mejora enormemente tu capacidad para usar tu mente y cuerpo.', en: 'Isha Kriya is a powerful 15-minute guided meditation for health and well-being. Through this practice you will learn to use your breath, thought, and awareness in a way that greatly enhances your ability to use your mind and body.', fr: 'Isha Kriya est une puissante méditation guidée de 15 minutes pour la santé et le bien-être. Grâce à cette pratique, vous apprendrez à utiliser votre respiration, votre pensée et votre conscience d\'une manière qui améliore considérablement votre capacité à utiliser votre esprit et votre corps.', ko: 'Isha Kriya는 건강과 웰빙을 위한 강력한 15분 안내 명상입니다. 이 수행을 통해 호흡, 생각, 알아차림을 사용하여 마음과 몸을 활용하는 능력을 크게 향상시키는 방법을 배우게 됩니다.', ja: 'Isha Kriyaは健康とウェルビーイングのための強力な15分のガイド付き瞑想です。この実践を通じて、呼吸、思考、氣づきを用いて、心と身体を使いこなす能力を大幅に高める方法を学びます。', zh: 'Isha Kriya是一个强大的15分钟引导冥想，促进健康与福祉。通过这一练习，你将学会以一种极大增强你运用心智和身体能力的方式，使用你的呼吸、思想和觉察。', it: 'Isha Kriya è una potente meditazione guidata di 15 minuti per la salute e il benessere. Attraverso questa pratica imparerai a usare il respiro, il pensiero e la consapevolezza in un modo che migliora notevolmente la tua capacità di usare la mente e il corpo.', "pt-BR": 'Isha Kriya é uma poderosa meditação guiada de 15 minutos para saúde e bem-estar. Através desta prática você aprenderá a usar sua respiração, pensamento e consciência de uma forma que melhora enormemente sua capacidade de usar sua mente e corpo.', pt: 'Isha Kriya é uma poderosa meditação guiada de 15 minutos para a saúde e bem-estar. Através desta prática aprenderá a usar a sua respiração, pensamento e consciência de uma forma que melhora enormemente a sua capacidade de usar a sua mente e corpo.', de: 'Isha Kriya ist eine kraftvolle 15-minütige geführte Meditation für Gesundheit und Wohlbefinden. Durch diese Praxis lernst du, deinen Atem, deine Gedanken und dein Bewusstsein so einzusetzen, dass deine Fähigkeit, Geist und Körper zu nutzen, erheblich verbessert wird.', ar: 'إيشا كريا هو تأمل موجه قوي لمدة 15 دقيقة للصحة والعافية. من خلال هذه الممارسة ستتعلم استخدام أنفاسك وفكرك ووعيك بطريقة تعزز بشكل كبير قدرتك على استخدام عقلك وجسدك.', nl: 'Isha Kriya is een krachtige 15 minuten begeleide meditatie voor gezondheid en welzijn. Door deze oefening leer je je adem, gedachten en bewustzijn te gebruiken op een manier die je vermogen om je geest en lichaam te gebruiken aanzienlijk verbetert.', hi: 'ईशा क्रिया स्वास्थ्य और कल्याण के लिए एक शक्तिशाली 15 मिनट का निर्देशित ध्यान है। इस अभ्यास के माध्यम से आप अपनी सांस, विचार और जागरूकता का इस तरह उपयोग करना सीखेंगे जो आपके मन और शरीर का उपयोग करने की आपकी क्षमता को बहुत बढ़ाता है।', pl: 'Isha Kriya to potężna 15-minutowa medytacja prowadzona dla zdrowia i dobrego samopoczucia. Dzięki tej praktyce nauczysz się używać oddechu, myśli i świadomości w sposób, który znacznie zwiększa twoją zdolność do korzystania z umysłu i ciała.', sv: 'Isha Kriya är en kraftfull 15-minuters guidad meditation för hälsa och välbefinnande. Genom denna praktik kommer du att lära dig att använda din andning, tanke och medvetenhet på ett sätt som avsevärt förbättrar din förmåga att använda ditt sinne och din kropp.', tr: 'Isha Kriya, sağlık ve esenlik için güçlü bir 15 dakikalık rehberli meditasyondur. Bu uygulama aracılığıyla nefesini, düşünceni ve farkındalığını, zihin ve bedenini kullanma yeteneğini büyük ölçüde artıracak şekilde kullanmayı öğreneceksin.', "zh-TW": 'Isha Kriya是一個強大的15分鐘引導冥想，用於健康和福祉。通過這個練習，你將學會使用你的呼吸、思想和覺知，從而極大地增強你運用心智和身體的能力。' },
  "miracle-of-mind.title": { es: 'Miracle of Mind', en: 'Miracle of Mind', fr: 'Miracle of Mind', ko: 'Miracle of Mind', ja: 'Miracle of Mind', zh: 'Miracle of Mind', it: 'Miracle of Mind', "pt-BR": 'Miracle of Mind', pt: 'Miracle of Mind', de: 'Miracle of Mind', ar: 'ميراكل أوف مايند', nl: 'Miracle of Mind', hi: 'Miracle of Mind', pl: 'Miracle of Mind', sv: 'Miracle of Mind', tr: 'Miracle of Mind', "zh-TW": 'Miracle of Mind' },
  "miracle-of-mind.subtitle": { es: 'Meditación guiada de 12 minutos', en: '12-minute guided meditation', fr: 'Méditation guidée de 12 minutes', ko: '12분 안내 명상', ja: '12分のガイド付き瞑想', zh: '12分钟引导冥想', it: 'Meditazione guidata di 12 minuti', "pt-BR": 'Meditação guiada de 12 minutos', pt: 'Meditação guiada de 12 minutos', de: '12-minütige geführte Meditation', ar: 'تأمل موجه لمدة 12 دقيقة', nl: '12 minuten begeleide meditatie', hi: '12 मिनट का निर्देशित ध्यान', pl: '12-minutowa medytacja prowadzona', sv: '12-minuters guidad meditation', tr: '12 dakikalık rehberli meditasyon', "zh-TW": '12分鐘引導冥想' },
  "miracle-of-mind.description": { es: 'Una poderosa meditación guiada diseñada por Sadhguru. Solo toma 12 minutos al día. Con instrucciones claras paso a paso y suaves campanillas, esta práctica establece una base sólida para el bienestar mental. Perfecta para principiantes y práctica diaria.', en: 'A powerful guided meditation designed by Sadhguru. It takes only 12 minutes a day. With clear step-by-step instructions and gentle bells, this practice establishes a solid foundation for mental well-being. Perfect for beginners and daily practice.', fr: 'Une puissante méditation guidée conçue par Sadhguru. Elle ne prend que 12 minutes par jour. Avec des instructions claires étape par étape et de douces cloches, cette pratique établit une base solide pour le bien-être mental. Parfaite pour les débutants et la pratique quotidienne.', ko: 'Sadhguru가 설계한 강력한 안내 명상입니다. 하루에 단 12분만 투자하면 됩니다. 명확한 단계별 지침과 부드러운 종소리와 함께, 이 수행은 정신적 웰빙을 위한 견고한 기초를 확립합니다. 초보자와 일상 수행에 완벽합니다.', ja: 'Sadhguruによってデザインされた強力なガイド付き瞑想です。1日たった12分で行えます。明確なステップバイステップの指示と優しいベルの音とともに、この実践は精神的なウェルビーイングのための確固たる基盤を築きます。初心者と日々の実践に最適です。', zh: '由Sadhguru设计的强大引导冥想。每天只需12分钟。通过清晰的分步指导和柔和的铃声，这一练习为心理健康奠定坚实基础。非常适合初学者和日常练习。', it: 'Una potente meditazione guidata progettata da Sadhguru. Richiede solo 12 minuti al giorno. Con istruzioni chiare passo dopo passo e delicate campane, questa pratica stabilisce una solida base per il benessere mentale. Perfetta per principianti e pratica quotidiana.', "pt-BR": 'Uma poderosa meditação guiada projetada por Sadhguru. Leva apenas 12 minutos por dia. Com instruções claras passo a passo e sinos suaves, esta prática estabelece uma base sólida para o bem-estar mental. Perfeita para iniciantes e prática diária.', pt: 'Uma poderosa meditação guiada concebida por Sadhguru. Leva apenas 12 minutos por dia. Com instruções claras passo a passo e sinos suaves, esta prática estabelece uma base sólida para o bem-estar mental. Perfeita para iniciantes e prática diária.', de: 'Eine kraftvolle geführte Meditation, entwickelt von Sadhguru. Sie dauert nur 12 Minuten am Tag. Mit klaren Schritt-für-Schritt-Anleitungen und sanften Glocken schafft diese Praxis eine solide Grundlage für geistiges Wohlbefinden. Perfekt für Anfänger und die tägliche Praxis.', ar: 'تأمل موجه قوي من تصميم سادجورو. يستغرق 7 دقائق فقط في اليوم. مع تعليمات واضحة خطوة بخطوة وأجراس لطيفة، تؤسس هذه الممارسة أساسًا متينًا للصحة النفسية. مثالية للمبتدئين والممارسة اليومية.', nl: 'Een krachtige begeleide meditatie ontworpen door Sadhguru. Het duurt slechts 12 minuten per dag. Met duidelijke stap-voor-stap instructies en zachte bellen legt deze oefening een solide basis voor mentaal welzijn. Perfect voor beginners en dagelijkse oefening.', hi: 'सद्गुरु द्वारा डिज़ाइन किया गया एक शक्तिशाली निर्देशित ध्यान। इसमें प्रतिदिन केवल 7 मिनट लगते हैं। स्पष्ट चरण-दर-चरण निर्देशों और कोमल घंटियों के साथ, यह अभ्यास मानसिक कल्याण के लिए एक ठोस नींव स्थापित करता है। शुरुआती और दैनिक अभ्यास के लिए एकदम सही।', pl: 'Potężna medytacja prowadzona zaprojektowana przez Sadhguru. Zajmuje tylko 12 minut dziennie. Dzięki jasnym instrukcjom krok po kroku i delikatnym dzwonkom ta praktyka tworzy solidny fundament dla dobrego samopoczucia psychicznego. Idealna dla początkujących i codziennej praktyki.', sv: 'En kraftfull guidad meditation designad av Sadhguru. Det tar bara 12 minuter om dagen. Med tydliga steg-för-steg-instruktioner och mjuka klockor etablerar denna praktik en solid grund för mentalt välbefinnande. Perfekt för nybörjare och daglig praktik.', tr: 'Sadhguru tarafından tasarlanmış güçlü bir rehberli meditasyon. Günde yalnızca 7 dakika sürer. Net adım adım talimatlar ve yumuşak çan sesleriyle bu uygulama zihinsel esenlik için sağlam bir temel oluşturur. Yeni başlayanlar ve günlük pratik için mükemmeldir.', "zh-TW": '由Sadhguru設計的強大引導冥想。每天只需7分鐘。通過清晰的逐步指引和柔和的鈴聲，這個練習為心理健康奠定了堅實的基礎。非常適合初學者和日常練習。' },
  "nada-yoga.title": { es: 'Nada Yoga', en: 'Nada Yoga', fr: 'Nada Yoga', ko: 'Nada Yoga', ja: 'Nada Yoga', zh: 'Nada Yoga', it: 'Nada Yoga', "pt-BR": 'Nada Yoga', pt: 'Nada Yoga', de: 'Nada Yoga', ar: 'نادا يوجا', nl: 'Nada Yoga', hi: 'नाद योग', pl: 'Nada Yoga', sv: 'Nada Yoga', tr: 'Nada Yoga', "zh-TW": 'Nada Yoga' },
  "nada-yoga.subtitle": { es: 'El yoga del sonido interior', en: 'The yoga of inner sound', fr: 'Le yoga du son intérieur', ko: '내면 소리의 요가', ja: '内なる音のヨガ', zh: '内在声音的瑜伽', it: 'Lo yoga del suono interiore', "pt-BR": 'A ioga do som interior', pt: 'O yoga do som interior', de: 'Der Yoga des inneren Klangs', ar: 'يوجا الصوت الداخلي', nl: 'De yoga van het innerlijke geluid', hi: 'आंतरिक ध्वनि का योग', pl: 'Joga wewnętrznego dźwięku', sv: 'Yogan för inre ljud', tr: 'İç sesin yogası', "zh-TW": '內在聲音的瑜伽' },
  "nada-yoga.description": { es: 'Nada Yoga es la ciencia de usar el sonido y la vibración para trascender los límites del ser. El sonido no es solo un medio de comunicación, es un puente hacia el infinito. A través del canto de AUM y la escucha profunda del sonido interior, esta práctica te lleva más allá del ruido mental hacia la paz interior.', en: 'Nada Yoga is the science of using sound and vibration to transcend the limits of being. Sound is not just a means of communication, it is a bridge to the infinite. Through AUM chanting and deep listening of the inner sound, this practice takes you beyond mental noise toward inner peace.', fr: 'Le Nada Yoga est la science qui utilise le son et la vibration pour transcender les limites de l\'être. Le son n\'est pas seulement un moyen de communication, c\'est un pont vers l\'infini. Par le chant d\'AUM et l\'écoute profonde du son intérieur, cette pratique vous emmène au-delà du bruit mental vers la paix intérieure.', ko: 'Nada Yoga는 소리와 진동을 사용하여 존재의 한계를 초월하는 과학입니다. 소리는 단순한 의사소통 수단이 아니라 무한으로 가는 다리입니다. AUM 차팅과 내면 소리의 깊은 듣기를 통해, 이 수행은 당신을 정신적 소음을 넘어 내면의 평화로 이끕니다.', ja: 'Nada Yogaは、音と振動を用いて存在の限界を超越する科学です。音は単なるコミュニケーションの手段ではなく、無限への架け橋です。AUMチャンティングと内なる音への深い傾聴を通じて、この実践はあなたを心の雑音を超えて内なる平和へと導きます。', zh: 'Nada Yoga是一门利用声音和振动来超越存在界限的科学。声音不仅是一种交流手段，它是通往无限的桥梁。通过AUM唱诵和深度聆听内在声音，这一练习带你超越精神噪音，走向内在平静。', it: 'Nada Yoga è la scienza di usare il suono e la vibrazione per trascendere i limiti dell\'essere. Il suono non è solo un mezzo di comunicazione, è un ponte verso l\'infinito. Attraverso il canto di AUM e l\'ascolto profondo del suono interiore, questa pratica ti porta oltre il rumore mentale verso la pace interiore.', "pt-BR": 'Nada Yoga é a ciência de usar o som e a vibração para transcender os limites do ser. O som não é apenas um meio de comunicação, é uma ponte para o infinito. Através do canto de AUM e da escuta profunda do som interior, esta prática leva você além do ruído mental em direção à paz interior.', pt: 'Nada Yoga é a ciência de usar o som e a vibração para transcender os limites do ser. O som não é apenas um meio de comunicação, é uma ponte para o infinito. Através do canto de AUM e da escuta profunda do som interior, esta prática leva-o para além do ruído mental em direção à paz interior.', de: 'Nada Yoga ist die Wissenschaft, Klang und Schwingung zu nutzen, um die Grenzen des Seins zu überwinden. Klang ist nicht nur ein Kommunikationsmittel, er ist eine Brücke zum Unendlichen. Durch das Rezitieren von AUM und das tiefe Lauschen des inneren Klangs führt dich diese Praxis über den mentalen Lärm hinaus zur inneren Ruhe.', ar: 'نادا يوجا هو علم استخدام الصوت والاهتزاز لتجاوز حدود الوجود. الصوت ليس مجرد وسيلة للتواصل، إنه جسر إلى اللانهاية. من خلال ترتيل أوم والاستماع العميق للصوت الداخلي، تأخذك هذه الممارسة إلى ما وراء الضوضاء الذهنية نحو السلام الداخلي.', nl: 'Nada Yoga is de wetenschap van het gebruik van geluid en vibratie om de grenzen van het zijn te overstijgen. Geluid is niet alleen een communicatiemiddel, het is een brug naar het oneindige. Door AUM te chanten en diep te luisteren naar het innerlijke geluid, brengt deze oefening je voorbij mentale ruis naar innerlijke vrede.', hi: 'नाद योग ध्वनि और कंपन का उपयोग करके अस्तित्व की सीमाओं को पार करने का विज्ञान है। ध्वनि केवल संचार का साधन नहीं है, यह अनंत का सेतु है। ओम के जाप और आंतरिक ध्वनि के गहन श्रवण के माध्यम से, यह अभ्यास आपको मानसिक शोर से परे आंतरिक शांति की ओर ले जाता है।', pl: 'Nada Yoga to nauka używania dźwięku i wibracji do przekraczania granic istnienia. Dźwięk to nie tylko środek komunikacji, to most do nieskończoności. Poprzez śpiewanie AUM i głębokie słuchanie wewnętrznego dźwięku, ta praktyka prowadzi cię poza hałas umysłu w kierunku wewnętrznego spokoju.', sv: 'Nada Yoga är vetenskapen om att använda ljud och vibration för att transcendera tillvarons gränser. Ljud är inte bara ett kommunikationsmedel, det är en bro till det oändliga. Genom Aum-mantra och djupt lyssnande på det inre ljudet tar denna praktik dig bortom mentalt brus mot inre frid.', tr: 'Nada Yoga, varlığın sınırlarını aşmak için ses ve titreşimi kullanma bilimidir. Ses yalnızca bir iletişim aracı değil, sonsuzluğa açılan bir köprüdür. AUM ilahisi ve iç sesin derin dinlenişi yoluyla bu uygulama seni zihinsel gürültünün ötesinde iç huzura götürür.', "zh-TW": 'Nada Yoga是利用聲音和振動超越存在界限的科學。聲音不僅僅是溝通的手段，它是通往無限的橋樑。通過AUM唱誦和深度聆聽內在聲音，這個練習帶你超越心靈噪音，走向內在平靜。' },
  "yoga-namaskar.title": { es: 'Yoga Namaskar', en: 'Yoga Namaskar', fr: 'Yoga Namaskar', ko: 'Yoga Namaskar', ja: 'Yoga Namaskar', zh: 'Yoga Namaskar', it: 'Yoga Namaskar', "pt-BR": 'Yoga Namaskar', pt: 'Yoga Namaskar', de: 'Yoga Namaskar', ar: 'يوجا ناماسكار', nl: 'Yoga Namaskar', hi: 'योग नमस्कार', pl: 'Yoga Namaskar', sv: 'Yoga Namaskar', tr: 'Yoga Namaskar', "zh-TW": 'Yoga Namaskar' },
  "yoga-namaskar.subtitle": { es: 'Rutina matutina de 10 minutos', en: '10-minute morning routine', fr: 'Routine matinale de 10 minutes', ko: '10분 아침 루틴', ja: '10分の朝のルーティン', zh: '10分钟晨间 routine', it: 'Routine mattutina di 10 minuti', "pt-BR": 'Rotina matinal de 10 minutos', pt: 'Rotina matinal de 10 minutos', de: '10-minütige Morgenroutine', ar: 'روتين صباحي لمدة 10 دقائق', nl: '10 minuten ochtendroutine', hi: '10 मिनट की सुबह की दिनचर्या', pl: '10-minutowa poranna rutyna', sv: '10-minuters morgonrutin', tr: '10 dakikalık sabah rutini', "zh-TW": '10分鐘早晨例行練習' },
  "yoga-namaskar.description": { es: 'Yoga Namaskar es una secuencia completa de 10 minutos para estirar y fortalecer la espalda. Esta poderosa práctica matutina activa la región lumbar de la columna y fortalece los músculos a lo largo de ella. Ideal para principiantes, puede hacerse en casa, en la oficina o en el parque.', en: 'Yoga Namaskar is a complete 10-minute sequence to stretch and strengthen the back. This powerful morning practice activates the lumbar region of the spine and strengthens the muscles along it. Ideal for beginners, it can be done at home, at the office, or in the park.', fr: 'Yoga Namaskar est une séquence complète de 10 minutes pour étirer et renforcer le dos. Cette puissante pratique matinale active la région lombaire de la colonne vertébrale et renforce les muscles qui l\'entourent. Idéale pour les débutants, elle peut se pratiquer à la maison, au bureau ou dans le parc.', ko: 'Yoga Namaskar는 등을 스트레칭하고 강화하는 완전한 10분 시퀀스입니다. 이 강력한 아침 수행은 척추의 요추 부위를 활성화하고 그 주변 근육을 강화합니다. 초보자에게 이상적이며 집, 사무실, 공원에서 할 수 있습니다.', ja: 'Yoga Namaskarは背中をストレッチし強化するための完全な10分のシークエンスです。この強力な朝の実践は、脊椎の腰部を活性化し、その周りの筋肉を強化します。初心者に理想的で、自宅、オフィス、公園で行うことができます。', zh: 'Yoga Namaskar是一个完整的10分钟序列，用于拉伸和强化背部。这一强大的晨间练习激活脊柱的腰部区域，并强化沿脊柱的肌肉。非常适合初学者，可以在家中、办公室或公园中进行。', it: 'Yoga Namaskar è una sequenza completa di 10 minuti per allungare e rafforzare la schiena. Questa potente pratica mattutina attiva la regione lombare della colonna vertebrale e rafforza i muscoli lungo di essa. Ideale per principianti, può essere fatto a casa, in ufficio o al parco.', "pt-BR": 'Yoga Namaskar é uma sequência completa de 10 minutos para alongar e fortalecer as costas. Esta poderosa prática matinal ativa a região lombar da coluna e fortalece os músculos ao longo dela. Ideal para iniciantes, pode ser feita em casa, no escritório ou no parque.', pt: 'Yoga Namaskar é uma sequência completa de 10 minutos para alongar e fortalecer as costas. Esta poderosa prática matinal ativa a região lombar da coluna e fortalece os músculos ao longo dela. Ideal para iniciantes, pode ser feita em casa, no escritório ou no parque.', de: 'Yoga Namaskar ist eine komplette 10-minütige Sequenz, um den Rücken zu dehnen und zu stärken. Diese kraftvolle Morgenpraxis aktiviert die Lendenwirbelsäule und stärkt die Muskeln entlang der Wirbelsäule. Ideal für Anfänger, kann sie zu Hause, im Büro oder im Park durchgeführt werden.', ar: 'يوجا ناماسكار هي تسلسل كامل لمدة 10 دقائق لتمديد وتقوية الظهر. هذه الممارسة الصباحية القوية تنشط المنطقة القطنية من العمود الفقري وتقوي العضلات على طوله. مثالية للمبتدئين، يمكن ممارستها في المنزل أو المكتب أو الحديقة.', nl: 'Yoga Namaskar is een complete 10 minuten durende reeks om de rug te strekken en te versterken. Deze krachtige ochtendoefening activeert de lumbale regio van de wervelkolom en versterkt de spieren erlangs. Ideaal voor beginners, het kan thuis, op kantoor of in het park worden gedaan.', hi: 'योग नमस्कार पीठ को खींचने और मजबूत करने के लिए एक संपूर्ण 10 मिनट का अनुक्रम है। यह शक्तिशाली सुबह का अभ्यास रीढ़ के काठ क्षेत्र को सक्रिय करता है और इसके साथ की मांसपेशियों को मजबूत करता है। शुरुआती लोगों के लिए आदर्श, इसे घर, कार्यालय या पार्क में किया जा सकता है।', pl: 'Yoga Namaskar to kompletna 10-minutowa sekwencja rozciągająca i wzmacniająca plecy. Ta potężna poranna praktyka aktywuje odcinek lędźwiowy kręgosłupa i wzmacnia mięśnie wzdłuż niego. Idealna dla początkujących, może być wykonywana w domu, w biurze lub w parku.', sv: 'Yoga Namaskar är en komplett 10-minuterssekvens för att sträcka och stärka ryggen. Denna kraftfulla morgonpraktik aktiverar ländryggen och stärker musklerna längs den. Idealisk för nybörjare, den kan göras hemma, på kontoret eller i parken.', tr: 'Yoga Namaskar, sırtı esnetmek ve güçlendirmek için tam bir 10 dakikalık sekansdır. Bu güçlü sabah pratiği omurganın bel bölgesini aktive eder ve boyunca uzanan kasları güçlendirir. Yeni başlayanlar için ideal olup evde, ofiste veya parkta yapılabilir.', "zh-TW": 'Yoga Namaskar是一個完整的10分鐘序列，用於伸展和強化背部。這個強大的晨間練習啟動脊柱的腰部區域並強化其周圍的肌肉。非常適合初學者，可以在家中、辦公室或公園進行。' },
  "nadi-shuddhi.title": { es: 'Nadi Shuddhi', en: 'Nadi Shuddhi', fr: 'Nadi Shuddhi', ko: 'Nadi Shuddhi', ja: 'Nadi Shuddhi', zh: 'Nadi Shuddhi', it: 'Nadi Shuddhi', "pt-BR": 'Nadi Shuddhi', pt: 'Nadi Shuddhi', de: 'Nadi Shuddhi', ar: 'نادي شودي', nl: 'Nadi Shuddhi', hi: 'नाड़ी शोधन', pl: 'Nadi Shuddhi', sv: 'Nadi Shuddhi', tr: 'Nadi Shuddhi', "zh-TW": 'Nadi Shuddhi' },
  "nadi-shuddhi.subtitle": { es: 'Limpieza de los canales energéticos', en: 'Cleansing of the energy channels', fr: 'Nettoyage des canaux énergétiques', ko: '에너지 채널 정화', ja: 'エネルギーチャンネルの浄化', zh: '能量通道的净化', it: 'Purificazione dei canali energetici', "pt-BR": 'Limpeza dos canais de energia', pt: 'Limpeza dos canais de energia', de: 'Reinigung der Energiekanäle', ar: 'تنظيف قنوات الطاقة', nl: 'Reiniging van de energiekanden', hi: 'ऊर्जा चैनलों की सफाई', pl: 'Oczyszczanie kanałów energetycznych', sv: 'Rengöring av energikanalerna', tr: 'Enerji kanallarının temizlenmesi', "zh-TW": '能量通道的淨化' },
  "nadi-shuddhi.description": { es: 'Nadi Shuddhi es una práctica simple pero poderosa de 5 minutos que limpia los nadis, los canales por los que fluye la energía pránica. Esta práctica resulta en un sistema equilibrado y bienestar psicológico. Guiada por Sadhguru.', en: 'Nadi Shuddhi is a simple yet powerful 5-minute practice that cleanses the nadis, the channels through which pranic energy flows. This practice results in a balanced system and psychological well-being. Guided by Sadhguru.', fr: 'Nadi Shuddhi est une pratique simple mais puissante de 5 minutes qui nettoie les nadis, les canaux par lesquels circule l\'énergie pranique. Cette pratique aboutit à un système équilibré et à un bien-être psychologique. Guidé par Sadhguru.', ko: 'Nadi Shuddhi는 프라나 에너지가 흐르는 채널인 나디를 정화하는 간단하지만 강력한 5분 수행입니다. 이 수행은 균형 잡힌 시스템과 심리적 웰빙을 가져옵니다. Sadhguru가 안내합니다.', ja: 'Nadi Shuddhiは、プラナエネルギーが流れるチャンネルであるナディを浄化する、シンプルでありながら強力な5分の実践です。この実践はバランスのとれたシステムと心理的ウェルビーイングをもたらします。Sadhguruがガイドします。', zh: 'Nadi Shuddhi是一个简单而强大的5分钟练习，用于净化nadis——生命能量流动的通道。这一练习带来平衡的系统与心理健康。由Sadhguru引导。', it: 'Nadi Shuddhi è una pratica semplice ma potente di 5 minuti che purifica i nadi, i canali attraverso cui fluisce l\'energia pranica. Questa pratica porta a un sistema equilibrato e benessere psicologico. Guidata da Sadhguru.', "pt-BR": 'Nadi Shuddhi é uma prática simples mas poderosa de 5 minutos que limpa os nadis, os canais por onde flui a energia prânica. Esta prática resulta em um sistema equilibrado e bem-estar psicológico. Guiada por Sadhguru.', pt: 'Nadi Shuddhi é uma prática simples mas poderosa de 5 minutos que limpa os nadis, os canais através dos quais a energia prânica flui. Esta prática resulta num sistema equilibrado e bem-estar psicológico. Guiada por Sadhguru.', de: 'Nadi Shuddhi ist eine einfache, aber kraftvolle 5-minütige Praxis, die die Nadis reinigt, die Kanäle, durch die die pranische Energie fließt. Diese Praxis führt zu einem ausgeglichenen System und psychischem Wohlbefinden. Angeleitet von Sadhguru.', ar: 'نادي شودي هي ممارسة بسيطة لكنها قوية لمدة 5 دقائق تنقي الناديس، القنوات التي تتدفق من خلالها الطاقة البرانية. تؤدي هذه الممارسة إلى نظام متوازن ورفاهية نفسية. من توجيه سادجورو.', nl: 'Nadi Shuddhi is een eenvoudige maar krachtige 5 minuten durende oefening die de nadi\'s reinigt, de kanalen waardoor pranische energie stroomt. Deze oefening resulteert in een gebalanceerd systeem en psychologisch welzijn. Begeleid door Sadhguru.', hi: 'नाड़ी शोधन एक सरल लेकिन शक्तिशाली 5 मिनट का अभ्यास है जो नाड़ियों, प्राणिक ऊर्जा के प्रवाह के चैनलों को साफ करता है। इस अभ्यास के परिणामस्वरूप एक संतुलित प्रणाली और मनोवैज्ञानिक कल्याण होता है। सद्गुरु द्वारा निर्देशित।', pl: 'Nadi Shuddhi to prosta, ale potężna 5-minutowa praktyka, która oczyszcza nadi, kanały, przez które przepływa energia praniczna. Ta praktyka prowadzi do zrównoważonego systemu i dobrego samopoczucia psychicznego. Prowadzona przez Sadhguru.', sv: 'Nadi Shuddhi är en enkel men kraftfull 5-minuterspraktik som renar nadis, kanalerna genom vilka pranisk energi flödar. Denna praktik resulterar i ett balanserat system och psykologiskt välbefinnande. Guidad av Sadhguru.', tr: 'Nadi Shuddhi, prana enerjisinin aktığı kanallar olan nadileri temizleyen basit ama güçlü 5 dakikalık bir pratiktir. Bu uygulama dengeli bir sistem ve psikolojik esenlik sağlar. Sadhguru rehberliğinde.', "zh-TW": 'Nadi Shuddhi是一個簡單而強大的5分鐘練習，用於淨化經絡（prana能量流動的通道）。這個練習帶來平衡的系統和心理健康。由Sadhguru引導。' },
  "chit-shakti-salud.title": { es: 'Chit Shakti para la Salud', en: 'Chit Shakti for Health', fr: 'Chit Shakti pour la Santé', ko: 'Chit Shakti 건강을 위한', ja: 'Chit Shakti 健康のための', zh: 'Chit Shakti 健康', it: 'Chit Shakti per la Salute', "pt-BR": 'Chit Shakti para a Saúde', pt: 'Chit Shakti para a Saúde', de: 'Chit Shakti für Gesundheit', ar: 'تشيت شاكتي للصحة', nl: 'Chit Shakti voor Gezondheid', hi: 'स्वास्थ्य के लिए चित शक्ति', pl: 'Chit Shakti dla Zdrowia', sv: 'Chit Shakti för Hälsa', tr: 'Chit Shakti Sağlık İçin', "zh-TW": 'Chit Shakti 健康' },
  "chit-shakti-salud.subtitle": { es: 'Meditación guiada gratuita', en: 'Free guided meditation', fr: 'Méditation guidée gratuite', ko: '무료 안내 명상', ja: '無料ガイド付き瞑想', zh: '免费引导冥想', it: 'Meditazione guidata gratuita', "pt-BR": 'Meditação guiada gratuita', pt: 'Meditação guiada gratuita', de: 'Kostenlose geführte Meditation', ar: 'تأمل موجه مجاني', nl: 'Gratis begeleide meditatie', hi: 'मुफ्त निर्देशित ध्यान', pl: 'Darmowa medytacja prowadzona', sv: 'Gratis guidad meditation', tr: 'Ücretsiz rehberli meditasyon', "zh-TW": '免費引導冥想' },
  "chit-shakti-salud.description": { es: 'Chit Shakti es una poderosa meditación guiada que utiliza el poder de la mente para crear tu realidad. Esta práctica está diseñada para la salud y el bienestar. A través de afirmaciones y visualización guiada por Sadhguru, activa la energía curativa dentro de ti.', en: 'Chit Shakti is a powerful guided meditation that uses the power of the mind to create your reality. This practice is designed for health and well-being. Through affirmations and guided visualization by Sadhguru, activate the healing energy within you.', fr: 'Chit Shakti est une puissante méditation guidée qui utilise le pouvoir de l\'esprit pour créer votre réalité. Cette pratique est conçue pour la santé et le bien-être. Grâce aux affirmations et à la visualisation guidée par Sadhguru, activez l\'énergie de guérison en vous.', ko: 'Chit Shakti는 마음의 힘을 사용하여 현실을 창조하는 강력한 안내 명상입니다. 이 수행은 건강과 웰빙을 위해 설계되었습니다. Sadhguru의 확언과 시각화 안내를 통해 당신 내면의 치유 에너지를 활성화하세요.', ja: 'Chit Shaktiは、心の力を使って現実を創造する強力なガイド付き瞑想です。この実践は健康とウェルビーイングのためにデザインされています。Sadhguruによるアファーメーションとガイド付きビジュアライゼーションを通じて、あなたの内なるヒーリングエネルギーを活性化させましょう。', zh: 'Chit Shakti是一种强大的引导冥想，利用心智的力量创造你的现实。这一练习专为健康和福祉设计。通过Sadhguru引导的肯定语和可视化，激活你内在的疗愈能量。', it: 'Chit Shakti è una potente meditazione guidata che usa il potere della mente per creare la tua realtà. Questa pratica è progettata per la salute e il benessere. Attraverso affermazioni e visualizzazione guidata da Sadhguru, attiva l\'energia curativa dentro di te.', "pt-BR": 'Chit Shakti é uma poderosa meditação guiada que usa o poder da mente para criar sua realidade. Esta prática é projetada para saúde e bem-estar. Através de afirmações e visualização guiada por Sadhguru, ative a energia curativa dentro de você.', pt: 'Chit Shakti é uma poderosa meditação guiada que usa o poder da mente para criar a sua realidade. Esta prática é concebida para a saúde e bem-estar. Através de afirmações e visualização guiada por Sadhguru, ative a energia de cura dentro de si.', de: 'Chit Shakti ist eine kraftvolle geführte Meditation, die die Kraft des Geistes nutzt, um deine Realität zu erschaffen. Diese Praxis ist für Gesundheit und Wohlbefinden konzipiert. Durch Affirmationen und geführte Visualisierung von Sadhguru aktivierst du die heilende Energie in dir.', ar: 'تشيت شاكتي هو تأمل موجه قوي يستخدم قوة العقل لخلق واقعك. هذه الممارسة مصممة للصحة والعافية. من خلال التأكيدات والتخيل الموجّه من سادجورو، فعّل الطاقة الشفائية في داخلك.', nl: 'Chit Shakti is een krachtige begeleide meditatie die de kracht van de geest gebruikt om je realiteit te creëren. Deze oefening is ontworpen voor gezondheid en welzijn. Door affirmaties en begeleide visualisatie door Sadhguru activeer je de helende energie in jezelf.', hi: 'चित शक्ति एक शक्तिशाली निर्देशित ध्यान है जो आपकी वास्तविकता बनाने के लिए मन की शक्ति का उपयोग करता है। यह अभ्यास स्वास्थ्य और कल्याण के लिए डिज़ाइन किया गया है। सद्गुरु द्वारा प्रतिज्ञान और निर्देशित दृश्य के माध्यम से, अपने भीतर उपचार ऊर्जा को सक्रिय करें।', pl: 'Chit Shakti to potężna medytacja prowadzona, która wykorzystuje siłę umysłu do tworzenia twojej rzeczywistości. Ta praktyka jest przeznaczona dla zdrowia i dobrego samopoczucia. Poprzez afirmacje i wizualizację prowadzoną przez Sadhguru, aktywuj uzdrawiającą energię w sobie.', sv: 'Chit Shakti är en kraftfull guidad meditation som använder sinnets kraft för att skapa din verklighet. Denna praktik är designad för hälsa och välbefinnande. Genom affirmationer och guidad visualisering av Sadhguru, aktivera den läkande energin inom dig.', tr: 'Chit Shakti, gerçekliğini yaratmak için zihnin gücünü kullanan güçlü bir rehberli meditasyondur. Bu uygulama sağlık ve esenlik için tasarlanmıştır. Sadhguru\'nun rehberliğinde onaylamalar ve görselleştirme yoluyla içindeki iyileştirici enerjiyi aktive et.', "zh-TW": 'Chit Shakti是一個強大的引導冥想，利用心靈的力量創造你的現實。這個練習專為健康和福祉而設計。通過Sadhguru引導的肯定語和可視化，激活你內在的療癒能量。' },
  "chit-shakti-amor.title": { es: 'Chit Shakti para el Amor', en: 'Chit Shakti for Love', fr: 'Chit Shakti pour l\'Amour', ko: 'Chit Shakti 사랑을 위한', ja: 'Chit Shakti 愛のための', zh: 'Chit Shakti 爱', it: 'Chit Shakti per l\'Amore', "pt-BR": 'Chit Shakti para o Amor', pt: 'Chit Shakti para o Amor', de: 'Chit Shakti für Liebe', ar: 'تشيت شاكتي للحب', nl: 'Chit Shakti voor Liefde', hi: 'प्रेम के लिए चित शक्ति', pl: 'Chit Shakti dla Miłości', sv: 'Chit Shakti för Kärlek', tr: 'Chit Shakti Sevgi İçin', "zh-TW": 'Chit Shakti 愛' },
  "chit-shakti-amor.subtitle": { es: 'Meditación guiada gratuita', en: 'Free guided meditation', fr: 'Méditation guidée gratuite', ko: '무료 안내 명상', ja: '無料ガイド付き瞑想', zh: '免费引导冥想', it: 'Meditazione guidata gratuita', "pt-BR": 'Meditação guiada gratuita', pt: 'Meditação guiada gratuita', de: 'Kostenlose geführte Meditation', ar: 'تأمل موجه مجاني', nl: 'Gratis begeleide meditatie', hi: 'मुफ्त निर्देशित ध्यान', pl: 'Darmowa medytacja prowadzona', sv: 'Gratis guidad meditation', tr: 'Ücretsiz rehberli meditasyon', "zh-TW": '免費引導冥想' },
  "chit-shakti-amor.description": { es: 'Chit Shakti es una poderosa meditación guiada que utiliza el poder de la mente para crear tu realidad. Esta práctica está diseñada para abrir tu corazón al amor en todas sus formas. Guiada por Sadhguru, utiliza afirmaciones y visualización para cultivar el amor y la compasión.', en: 'Chit Shakti is a powerful guided meditation that uses the power of the mind to create your reality. This practice is designed to open your heart to love in all its forms. Guided by Sadhguru, it uses affirmations and visualization to cultivate love and compassion.', fr: 'Chit Shakti est une puissante méditation guidée qui utilise le pouvoir de l\'esprit pour créer votre réalité. Cette pratique est conçue pour ouvrir votre cœur à l\'amour sous toutes ses formes. Guidée par Sadhguru, elle utilise les affirmations et la visualisation pour cultiver l\'amour et la compassion.', ko: 'Chit Shakti는 마음의 힘을 사용하여 현실을 창조하는 강력한 안내 명상입니다. 이 수행은 모든 형태의 사랑에 마음을 여는 것을 목적으로 합니다. Sadhguru가 안내하며, 확언과 시각화를 사용하여 사랑과 연민을 기릅니다.', ja: 'Chit Shaktiは、心の力を使って現実を創造する強力なガイド付き瞑想です。この実践は、あらゆる形の愛に心を開くためにデザインされています。Sadhguruがガイドし、アファーメーションとビジュアライゼーションを用いて愛と思いやりを育みます。', zh: 'Chit Shakti是一种强大的引导冥想，利用心智的力量创造你的现实。这一练习旨在让你敞开心扉，拥抱各种形式的爱。由Sadhguru引导，使用肯定语和可视化来培养爱与慈悲。', it: 'Chit Shakti è una potente meditazione guidata che usa il potere della mente per creare la tua realtà. Questa pratica è progettata per aprire il tuo cuore all\'amore in tutte le sue forme. Guidata da Sadhguru, usa affermazioni e visualizzazione per coltivare amore e compassione.', "pt-BR": 'Chit Shakti é uma poderosa meditação guiada que usa o poder da mente para criar sua realidade. Esta prática é projetada para abrir seu coração ao amor em todas as suas formas. Guiada por Sadhguru, usa afirmações e visualização para cultivar amor e compaixão.', pt: 'Chit Shakti é uma poderosa meditação guiada que usa o poder da mente para criar a sua realidade. Esta prática é concebida para abrir o seu coração ao amor em todas as suas formas. Guiada por Sadhguru, usa afirmações e visualização para cultivar o amor e a compaixão.', de: 'Chit Shakti ist eine kraftvolle geführte Meditation, die die Kraft des Geistes nutzt, um deine Realität zu erschaffen. Diese Praxis ist darauf ausgerichtet, dein Herz für die Liebe in all ihren Formen zu öffnen. Angeleitet von Sadhguru, nutzt sie Affirmationen und Visualisierung, um Liebe und Mitgefühl zu kultivieren.', ar: 'تشيت شاكتي هو تأمل موجه قوي يستخدم قوة العقل لخلق واقعك. هذه الممارسة مصممة لفتح قلبك للحب بكل أشكاله. من توجيه سادجورو، يستخدم التأكيدات والتخيل لتنمية الحب والرحمة.', nl: 'Chit Shakti is een krachtige begeleide meditatie die de kracht van de geest gebruikt om je realiteit te creëren. Deze oefening is ontworpen om je hart te openen voor liefde in al haar vormen. Begeleid door Sadhguru, gebruikt het affirmaties en visualisatie om liefde en compassie te cultiveren.', hi: 'चित शक्ति एक शक्तिशाली निर्देशित ध्यान है जो आपकी वास्तविकता बनाने के लिए मन की शक्ति का उपयोग करता है। यह अभ्यास आपके दिल को सभी रूपों में प्रेम के लिए खोलने के लिए डिज़ाइन किया गया है। सद्गुरु द्वारा निर्देशित, यह प्रेम और करुणा विकसित करने के लिए प्रतिज्ञान और दृश्य का उपयोग करता है।', pl: 'Chit Shakti to potężna medytacja prowadzona, która wykorzystuje siłę umysłu do tworzenia twojej rzeczywistości. Ta praktyka jest zaprojektowana, aby otworzyć twoje serce na miłość we wszystkich jej formach. Prowadzona przez Sadhguru, wykorzystuje afirmacje i wizualizację do kultywowania miłości i współczucia.', sv: 'Chit Shakti är en kraftfull guidad meditation som använder sinnets kraft för att skapa din verklighet. Denna praktik är designad för att öppna ditt hjärta för kärlek i alla dess former. Guidad av Sadhguru, den använder affirmationer och visualisering för att odla kärlek och medkänsla.', tr: 'Chit Shakti, gerçekliğini yaratmak için zihnin gücünü kullanan güçlü bir rehberli meditasyondur. Bu uygulama kalbini sevgiye tüm biçimleriyle açmak için tasarlanmıştır. Sadhguru rehberliğinde sevgi ve şefkati geliştirmek için onaylamalar ve görselleştirme kullanır.', "zh-TW": 'Chit Shakti是一個強大的引導冥想，利用心靈的力量創造你的現實。這個練習旨在讓你的心向所有形式的愛敞開。由Sadhguru引導，使用肯定語和可視化來培養愛與慈悲。' },
  "no-soy-el-cuerpo.title": { es: 'No soy el Cuerpo — Tampoco soy la Mente', en: 'I am not the Body — Neither am I the Mind', fr: 'Je ne suis pas le Corps — Je ne suis pas non plus l\'Esprit', ko: '나는 몸이 아니다 — 나는 마음도 아니다', ja: '私は身体ではない — 私は心でもない', zh: '我不是身体——我也不是头脑', it: 'Non sono il Corpo — Non sono nemmeno la Mente', "pt-BR": 'Não sou o Corpo — Tampouco sou a Mente', pt: 'Não sou o Corpo — Também não sou a Mente', de: 'Ich bin nicht der Körper — Ich bin auch nicht der Geist', ar: 'أنا لست الجسد — ولست العقل أيضًا', nl: 'Ik ben niet het Lichaam — Ik ben ook niet de Geest', hi: 'मैं शरीर नहीं हूं — न ही मैं मन हूं', pl: 'Nie jestem Ciałem — Nie jestem też Umysłem', sv: 'Jag är inte Kroppen — Inte heller är jag Sinnet', tr: 'Beden Değilim — Zihin de Değilim', "zh-TW": '我不是身體——我也不是心靈' },
  "no-soy-el-cuerpo.subtitle": { es: '7 minutos para recordar tu verdadera naturaleza', en: '7 minutes to remember your true nature', fr: '7 minutes pour vous souvenir de votre vraie nature', ko: '당신의 진정한 본성을 기억하는 7분', ja: '本当の自分を思い出す7分間', zh: '用7分钟记起你的真实本质', it: '7 minuti per ricordare la tua vera natura', "pt-BR": '7 minutos para lembrar sua verdadeira natureza', pt: '7 minutos para lembrar a sua verdadeira natureza', de: '7 Minuten, um sich deiner wahren Natur zu erinnern', ar: '7 دقائق لتتذكر طبيعتك الحقيقية', nl: '7 minuten om je ware aard te herinneren', hi: 'अपनी सच्ची प्रकृति को याद करने के लिए 7 मिनट', pl: '7 minut, by zapamiętać swoją prawdziwą naturę', sv: '7 minuter för att komma ihåg din sanna natur', tr: 'Gerçek doğanı hatırlamak için 7 dakika', "zh-TW": '7分鐘憶起你的真實本性' },
  "no-soy-el-cuerpo.description": { es: 'Una meditación profunda basada en la enseñanza advaita. Al afirmar "No soy el Cuerpo" en la inhalación y "Tampoco soy la Mente" en la exhalación, trasciendes las identificaciones limitantes y despiertas a tu verdadera esencia.', en: 'A deep meditation based on advaita teaching. By affirming "I am not the Body" on the inhale and "Neither am I the Mind" on the exhale, you transcend limiting identifications and awaken to your true essence.', fr: 'Une méditation profonde basée sur l\'enseignement de l\'Advaita. En affirmant « Je ne suis pas le Corps » à l\'inspiration et « Je ne suis pas non plus l\'Esprit » à l\'expiration, vous transcendez les identifications limitantes et vous éveillez à votre véritable essence.', ko: 'Advaita 가르침에 기반한 깊은 명상입니다. 들이쉴 때 "나는 몸이 아니다"라고, 내쉴 때 "나는 마음도 아니다"라고 긍정함으로써, 제한적인 동일시를 초월하고 진정한 본질에 깨어납니다.', ja: 'Advaitaの教えに基づく深い瞑想です。息を吸うときに「私は身体ではない」と、息を吐くときに「私は心でもない」とアファームすることで、限定的な同一化を超越し、真の本質に目覚めます。', zh: '基于不二论教导的深度冥想。通过在吸气时肯定“我不是身体”，呼气时肯定“我也不是头脑”，你超越限制性的认同，觉醒到你的真实本质。', it: 'Una meditazione profonda basata sull\'insegnamento Advaita. Affermando "Non sono il Corpo" durante l\'inspiro e "Non sono nemmeno la Mente" durante l\'espiro, trascendi le identificazioni limitanti e ti risvegli alla tua vera essenza.', "pt-BR": 'Uma meditação profunda baseada no ensinamento Advaita. Ao afirmar "Não sou o Corpo" na inspiração e "Tampouco sou a Mente" na expiração, você transcende identificações limitantes e desperta para sua verdadeira essência.', pt: 'Uma meditação profunda baseada no ensinamento advaita. Ao afirmar "Não sou o Corpo" na inspiração e "Também não sou a Mente" na expiração, transcende identificações limitadoras e desperta para a sua verdadeira essência.', de: 'Eine tiefgehende Meditation basierend auf der Advaita-Lehre. Indem du beim Einatmen „Ich bin nicht der Körper" und beim Ausatmen „Ich bin auch nicht der Geist" affirmierst, überwindest du begrenzende Identifikationen und erwachst zu deiner wahren Essenz.', ar: 'تأمل عميق قائم على تعاليم أدفايتا. من خلال التأكيد على „أنا لست الجسد" عند الشهيق و „ولست العقل أيضًا" عند الزفير، تتجاوز التحديدات المحدودة وتستيقظ على جوهرك الحقيقي.', nl: 'Een diepe meditatie gebaseerd op de advaita-leer. Door te bevestigen „Ik ben niet het Lichaam" bij het inademen en „Ik ben ook niet de Geest" bij het uitademen, overstijg je beperkende identificaties en ontwaak je tot je ware essentie.', hi: 'अद्वैत शिक्षा पर आधारित एक गहन ध्यान। श्वास लेते हुए "मैं शरीर नहीं हूं" और श्वास छोड़ते हुए "न ही मैं मन हूं" का प्रतिज्ञान करके, आप सीमित पहचानों को पार करते हैं और अपने सच्चे सार की ओर जागते हैं।', pl: 'Głęboka medytacja oparta na nauce adwajty. Potwierdzając "Nie jestem Ciałem" na wdechu i "Nie jestem też Umysłem" na wydechu, przekraczasz ograniczające identyfikacje i budzisz się do swojej prawdziwej esencji.', sv: 'En djup meditation baserad på advaita-läran. Genom att bekräfta "Jag är inte Kroppen" på inandningen och "Inte heller är jag Sinnet" på utandningen, transcenderar du begränsande identifikationer och vaknar till din sanna essens.', tr: 'Advaita öğretisine dayanan derin bir meditasyon. Nefes alırken "Beden Değilim" ve nefes verirken "Zihin de Değilim" diyerek onaylayarak, sınırlayıcı özdeşleşmeleri aşar ve gerçek özüne uyanırsın.', "zh-TW": '基於不二論教義的深度冥想。吸氣時肯定「我不是身體」，呼氣時肯定「我也不是心靈」，你將超越限制性的認同，覺醒到你的真實本質。' },
  "yoga-exito.title": { es: 'Yoga para el Éxito', en: 'Yoga for Success', fr: 'Yoga pour le Succès', ko: '성공을 위한 요가', ja: '成功のためのヨガ', zh: '成功瑜伽', it: 'Yoga per il Successo', "pt-BR": 'Yoga para o Sucesso', pt: 'Yoga para o Sucesso', de: 'Yoga für Erfolg', ar: 'يوجا للنجاح', nl: 'Yoga voor Succes', hi: 'सफलता के लिए योग', pl: 'Joga dla Sukcesu', sv: 'Yoga för Framgång', tr: 'Başarı İçin Yoga', "zh-TW": '成功瑜伽' },
  "yoga-exito.subtitle": { es: '5 minutos', en: '5 minutes', fr: '5 minutes', ko: '5분', ja: '5分', zh: '5分钟', it: '5 minuti', "pt-BR": '5 minutos', pt: '5 minutos', de: '5 Minuten', ar: '5 دقائق', nl: '5 minuten', hi: '5 मिनट', pl: '5 minut', sv: '5 minuter', tr: '5 dakika', "zh-TW": '5分鐘' },
  "yoga-exito.description": { es: 'Una práctica corta de yoga guiada por Sadhguru para activar la energía del éxito en tu sistema. En solo 5 minutos, alinea tu cuerpo y mente para atraer prosperidad y logros.', en: 'A short yoga practice guided by Sadhguru to activate the energy of success in your system. In just 5 minutes, align your body and mind to attract prosperity and achievements.', fr: 'Une courte pratique de yoga guidée par Sadhguru pour activer l\'énergie du succès dans votre système. En seulement 5 minutes, alignez votre corps et votre esprit pour attirer la prospérité et les réalisations.', ko: 'Sadhguru가 안내하는 짧은 요가 수행으로 당신의 시스템에서 성공의 에너지를 활성화합니다. 단 5분 만에 몸과 마음을 정렬하여 번영과 성취를 끌어들이세요.', ja: 'Sadhguruがガイドする短いヨガの実践で、あなたのシステムの成功のエネルギーを活性化します。たった5分で、身体と心を整えて繁栄と達成を引き寄せましょう。', zh: '由Sadhguru引导的简短瑜伽练习，激活你系统中成功的力量。仅需5分钟，让你的身体和头脑对齐，吸引繁荣与成就。', it: 'Una breve pratica yoga guidata da Sadhguru per attivare l\'energia del successo nel tuo sistema. In soli 5 minuti, allinea corpo e mente per attrarre prosperità e risultati.', "pt-BR": 'Uma breve prática de yoga guiada por Sadhguru para ativar a energia do sucesso em seu sistema. Em apenas 5 minutos, alinhe seu corpo e mente para atrair prosperidade e realizações.', pt: 'Uma prática curta de yoga guiada por Sadhguru para ativar a energia do sucesso no seu sistema. Em apenas 5 minutos, alinhe o seu corpo e mente para atrair prosperidade e conquistas.', de: 'Eine kurze Yoga-Praxis unter der Leitung von Sadhguru, um die Energie des Erfolgs in deinem System zu aktivieren. In nur 5 Minuten richtest du deinen Körper und Geist aus, um Wohlstand und Erfolge anzuziehen.', ar: 'ممارسة يوجا قصيرة من توجيه سادجورو لتنشيط طاقة النجاح في نظامك. في 5 دقائق فقط، انسجم جسدك وعقلك لجذب الرخاء والإنجازات.', nl: 'Een korte yogabeoefening onder leiding van Sadhguru om de energie van succes in je systeem te activeren. In slechts 5 minuten stem je je lichaam en geest af op het aantrekken van voorspoed en prestaties.', hi: 'सद्गुरु द्वारा निर्देशित एक छोटी योग प्रैक्टिस जो आपके सिस्टम में सफलता की ऊर्जा को सक्रिय करती है। केवल 5 मिनट में, समृद्धि और उपलब्धियों को आकर्षित करने के लिए अपने शरीर और मन को संरेखित करें।', pl: 'Krótka praktyka jogi prowadzona przez Sadhguru, aby aktywować energię sukcesu w twoim systemie. W zaledwie 5 minut wyrównaj swoje ciało i umysł, aby przyciągnąć dobrobyt i osiągnięcia.', sv: 'En kort yogapraktik guidad av Sadhguru för att aktivera framgångens energi i ditt system. På bara 5 minuter, rikta in din kropp och ditt sinne för att attrahera välstånd och prestationer.', tr: 'Sadhguru rehberliğinde sisteminde başarı enerjisini aktive etmek için kısa bir yoga pratiği. Sadece 5 dakikada bedenini ve zihnini refah ve başarı çekecek şekilde hizala.', "zh-TW": '由Sadhguru引導的短瑜伽練習，用於激活你系統中的成功能量。只需5分鐘，調整你的身心以吸引繁榮和成就。' },
  "yoga-espalda.title": { es: 'Yoga para el Dolor de Espalda', en: 'Yoga for Back Pain', fr: 'Yoga pour les Maux de Dos', ko: '요가 for Back Pain', ja: '腰痛のためのヨガ', zh: '缓解背痛瑜伽', it: 'Yoga per il Mal di Schiena', "pt-BR": 'Yoga para Dor nas Costas', pt: 'Yoga para a Dor nas Costas', de: 'Yoga bei Rückenschmerzen', ar: 'يوجا لآلام الظهر', nl: 'Yoga voor Rugpijn', hi: 'पीठ दर्द के लिए योग', pl: 'Joga na Ból Pleców', sv: 'Yoga mot Ryggsmärta', tr: 'Sırt Ağrısı İçin Yoga', "zh-TW": '背痛舒緩瑜伽' },
  "yoga-espalda.subtitle": { es: '10 minutos', en: '10 minutes', fr: '10 minutes', ko: '10분', ja: '10分', zh: '10分钟', it: '10 minuti', "pt-BR": '10 minutos', pt: '10 minutos', de: '10 Minuten', ar: '10 دقائق', nl: '10 minuten', hi: '10 मिनट', pl: '10 minut', sv: '10 minuter', tr: '10 dakika', "zh-TW": '10分鐘' },
  "yoga-espalda.description": { es: 'Una práctica de 10 minutos guiada por Sadhguru para aliviar el dolor de espalda. Estira y fortalece la columna con movimientos suaves y conscientes.', en: 'A 10-minute practice guided by Sadhguru to relieve back pain. Stretch and strengthen your spine with gentle, mindful movements.', fr: 'Une pratique de 10 minutes guidée par Sadhguru pour soulager les maux de dos. Étirez et renforcez votre colonne vertébrale avec des mouvements doux et conscients.', ko: 'Sadhguru가 안내하는 10분 수행으로 허리 통증을 완화합니다. 부드럽고 의식적인 움직임으로 척추를 스트레칭하고 강화하세요.', ja: 'Sadhguruがガイドする10分の実践で腰痛を和らげます。優しく意識的な動きで脊椎をストレッチし強化しましょう。', zh: '由Sadhguru引导的10分钟练习，缓解背痛。通过柔和、有意识的动作拉伸和强化脊柱。', it: 'Una pratica di 10 minuti guidata da Sadhguru per alleviare il mal di schiena. Allunga e rafforza la colonna vertebrale con movimenti dolci e consapevoli.', "pt-BR": 'Uma prática de 10 minutos guiada por Sadhguru para aliviar dores nas costas. Alongue e fortaleça sua coluna com movimentos suaves e conscientes.', pt: 'Uma prática de 10 minutos guiada por Sadhguru para aliviar a dor nas costas. Alongue e fortaleça a sua coluna com movimentos suaves e conscientes.', de: 'Eine 10-minütige Praxis unter der Leitung von Sadhguru zur Linderung von Rückenschmerzen. Dehne und stärke deine Wirbelsäule mit sanften, achtsamen Bewegungen.', ar: 'ممارسة لمدة 10 دقائق من توجيه سادجورو لتخفيف آلام الظهر. مدّ وقعّ عمودك الفقري بحركات لطيفة وواعية.', nl: 'Een 10 minuten durende oefening onder leiding van Sadhguru om rugpijn te verlichten. Rek en versterk je ruggengraat met zachte, bewuste bewegingen.', hi: 'पीठ दर्द से राहत के लिए सद्गुरु द्वारा निर्देशित एक 10 मिनट का अभ्यास। कोमल, सचेत गतिविधियों से अपनी रीढ़ को खींचें और मजबूत करें।', pl: '10-minutowa praktyka prowadzona przez Sadhguru łagodząca ból pleców. Rozciągnij i wzmocnij swój kręgosłup delikatnymi, świadomymi ruchami.', sv: 'En 10-minuterspraktik guidad av Sadhguru för att lindra ryggsmärta. Sträck och stärk din ryggrad med mjuka, medvetna rörelser.', tr: 'Sadhguru rehberliğinde sırt ağrısını hafifletmek için 10 dakikalık bir pratik. Omurganı yumuşak ve bilinçli hareketlerle esnet ve güçlendir.', "zh-TW": '由Sadhguru引導的10分鐘練習，用於緩解背痛。通過溫和、正念的動作伸展和強化你的脊柱。' },
  "explorar-interior.title": { es: 'Explorar tu Interior', en: 'Explore Your Inner Self', fr: 'Explorez votre Être Intérieur', ko: '내면 탐험', ja: '内なる自分を探求する', zh: '探索你的内在自我', it: 'Esplora il Tuo Sé Interiore', "pt-BR": 'Explore Seu Interior', pt: 'Explore o seu Interior', de: 'Erkunde dein Inneres', ar: 'استكشف ذاتك الداخلية', nl: 'Verken je Innerlijke Zelf', hi: 'अपने आंतरिक स्व की खोज करें', pl: 'Poznaj swoje Wewnętrzne Ja', sv: 'Utforska ditt Inre Jag', tr: 'İç Benliğini Keşfet', "zh-TW": '探索你的內在' },
  "explorar-interior.subtitle": { es: '5 minutos', en: '5 minutes', fr: '5 minutes', ko: '5분', ja: '5分', zh: '5分钟', it: '5 minuti', "pt-BR": '5 minutos', pt: '5 minutos', de: '5 Minuten', ar: '5 دقائق', nl: '5 minuten', hi: '5 मिनट', pl: '5 minut', sv: '5 minuter', tr: '5 dakika', "zh-TW": '5分鐘' },
  "explorar-interior.description": { es: 'Una meditación guiada de 5 minutos para explorar tu mundo interior. Sadhguru te conduce a las profundidades de tu ser en este viaje introspectivo.', en: 'A 5-minute guided meditation to explore your inner world. Sadhguru takes you into the depths of your being on this introspective journey.', fr: 'Une méditation guidée de 5 minutes pour explorer votre monde intérieur. Sadhguru vous emmène dans les profondeurs de votre être dans ce voyage introspectif.', ko: '내면 세계를 탐험하는 5분 안내 명상입니다. Sadhguru가 이 내성적 여정에서 당신을 존재의 깊이로 인도합니다.', ja: '内なる世界を探求する5分間のガイド付き瞑想です。Sadhguruがこの内省の旅であなたを存在の深みへと導きます。', zh: '一段5分钟的引导冥想，探索你的内在世界。Sadhguru带你进入存在的深处，踏上这段内省之旅。', it: 'Una meditazione guidata di 5 minuti per esplorare il tuo mondo interiore. Sadhguru ti conduce nelle profondità del tuo essere in questo viaggio introspettivo.', "pt-BR": 'Uma meditação guiada de 5 minutos para explorar seu mundo interior. Sadhguru leva você às profundezas do seu ser nesta jornada introspectiva.', pt: 'Uma meditação guiada de 5 minutos para explorar o seu mundo interior. Sadhguru leva-o às profundezas do seu ser nesta viagem introspetiva.', de: 'Eine 5-minütige geführte Meditation, um deine innere Welt zu erkunden. Sadhguru nimmt dich auf dieser introspektiven Reise mit in die Tiefen deines Seins.', ar: 'تأمل موجه لمدة 5 دقائق لاستكشاف عالمك الداخلي. يأخذك سادجورو إلى أعماق كيانك في هذه الرحلة الاستبطانية.', nl: 'Een 5 minuten begeleide meditatie om je innerlijke wereld te verkennen. Sadhguru neemt je mee naar de diepten van je wezen op deze introspectieve reis.', hi: 'अपनी आंतरिक दुनिया का पता लगाने के लिए एक 5 मिनट का निर्देशित ध्यान। सद्गुरु इस आत्मनिरीक्षण यात्रा पर आपको आपके अस्तित्व की गहराइयों में ले जाते हैं।', pl: '5-minutowa medytacja prowadzona, aby poznać swój wewnętrzny świat. Sadhguru zabiera cię w głąb twojego jestestwa w tę introspekcyjną podróż.', sv: 'En 5-minuters guidad meditation för att utforska din inre värld. Sadhguru tar dig in i djupet av ditt väsen på denna introspektiva resa.', tr: 'İç dünyanı keşfetmek için 5 dakikalık rehberli bir meditasyon. Sadhguru bu içe dönük yolculukta seni varlığının derinliklerine götürür.', "zh-TW": '一個5分鐘的引導冥想，用於探索你的內在世界。Sadhguru帶領你進入存在的深處，踏上這段內省之旅。' },
  "isha-upa-yoga.title": { es: 'Isha Upa Yoga', en: 'Isha Upa Yoga', fr: 'Isha Upa Yoga', ko: 'Isha Upa Yoga', ja: 'Isha Upa Yoga', zh: 'Isha Upa Yoga', it: 'Isha Upa Yoga', "pt-BR": 'Isha Upa Yoga', pt: 'Isha Upa Yoga', de: 'Isha Upa Yoga', ar: 'إيشا أوبا يوجا', nl: 'Isha Upa Yoga', hi: 'ईशा उप योग', pl: 'Isha Upa Yoga', sv: 'Isha Upa Yoga', tr: 'Isha Upa Yoga', "zh-TW": 'Isha Upa Yoga' },
  "isha-upa-yoga.subtitle": { es: 'Prácticas guiadas', en: 'Guided practices', fr: 'Pratiques guidées', ko: '안내 수행', ja: 'ガイド付きプラクティス', zh: '引导练习', it: 'Pratiche guidate', "pt-BR": 'Práticas guiadas', pt: 'Práticas guiadas', de: 'Geführte Übungen', ar: 'ممارسات موجهة', nl: 'Begeleide oefeningen', hi: 'निर्देशित अभ्यास', pl: 'Praktyki prowadzone', sv: 'Guidan praktiker', tr: 'Rehberli pratikler', "zh-TW": '引導練習' },
  "isha-upa-yoga.description": { es: 'Una colección de prácticas guiadas de Isha Upa Yoga con Sadhguru. Estas poderosas rutinas están diseñadas para activar las articulaciones, rejuvenecer el sistema y traer salud y bienestar a tu vida.', en: 'A collection of guided Isha Upa Yoga practices with Sadhguru. These powerful routines are designed to activate the joints, rejuvenate the system, and bring health and well-being to your life.', fr: 'Une collection de pratiques guidées d\'Isha Upa Yoga avec Sadhguru. Ces puissantes routines sont conçues pour activer les articulations, rajeunir le système et apporter santé et bien-être dans votre vie.', ko: 'Sadhguru와 함께하는 안내된 Isha Upa Yoga 수행 모음입니다. 이 강력한 루틴은 관절을 활성화하고 시스템을 활력화하며 건강과 웰빙을 가져오도록 설계되었습니다.', ja: 'Sadhguruとともに行うガイド付きIsha Upa Yogaの実践集です。これらの強力なルーティンは、関節を活性化し、システムを若返らせ、健康とウェルビーイングをあなたの人生にもたらすようにデザインされています。', zh: '与Sadhguru一起的Isha Upa Yoga引导练习合集。这些强大的序列旨在激活关节、焕活系统，并为你的生活带来健康与福祉。', it: 'Una raccolta di pratiche guidate di Isha Upa Yoga con Sadhguru. Queste potenti routine sono progettate per attivare le articolazioni, ringiovanire il sistema e portare salute e benessere nella tua vita.', "pt-BR": 'Uma coleção de práticas guiadas de Isha Upa Yoga com Sadhguru. Estas poderosas rotinas são projetadas para ativar as articulações, rejuvenescer o sistema e trazer saúde e bem-estar para sua vida.', pt: 'Uma coleção de práticas guiadas de Isha Upa Yoga com Sadhguru. Estas rotinas poderosas são concebidas para ativar as articulações, rejuvenescer o sistema e trazer saúde e bem-estar à sua vida.', de: 'Eine Sammlung geführter Isha Upa Yoga-Übungen mit Sadhguru. Diese kraftvollen Routinen wurden entwickelt, um die Gelenke zu aktivieren, das System zu verjüngen und Gesundheit und Wohlbefinden in dein Leben zu bringen.', ar: 'مجموعة من ممارسات إيشا أوبا يوجا الموجهة مع سادجورو. صُممت هذه الروتينات القوية لتنشيط المفاصل، وتجديد النظام، وجلب الصحة والعافية إلى حياتك.', nl: 'Een verzameling begeleide Isha Upa Yoga-oefeningen met Sadhguru. Deze krachtige routines zijn ontworpen om de gewrichten te activeren, het systeem te verjongen en gezondheid en welzijn in je leven te brengen.', hi: 'सद्गुरु के साथ निर्देशित ईशा उप योग अभ्यासों का एक संग्रह। ये शक्तिशाली दिनचर्याएं जोड़ों को सक्रिय करने, सिस्टम को फिर से जीवंत करने और आपके जीवन में स्वास्थ्य और कल्याण लाने के लिए डिज़ाइन की गई हैं।', pl: 'Kolekcja prowadzonych praktyk Isha Upa Yoga z Sadhguru. Te potężne rutyny są zaprojektowane, aby aktywować stawy, odmłodzić system i wnieść zdrowie i dobre samopoczucie do twojego życia.', sv: 'En samling guidade Isha Upa Yoga-praktiker med Sadhguru. Dessa kraftfulla rutiner är designade för att aktivera lederna, föryngra systemet och bringa hälsa och välbefinnande till ditt liv.', tr: 'Sadhguru ile rehberli Isha Upa Yoga pratiklerinden oluşan bir koleksiyon. Bu güçlü rutinler eklemleri aktive etmek, sistemi gençleştirmek ve hayatına sağlık ve esenlik getirmek için tasarlanmıştır.', "zh-TW": '與Sadhguru一起的引導式Isha Upa Yoga練習集。這些強大的例行程序旨在激活關節、 rejuvenate 系統，並為你的生活帶來健康和福祉。' },
};

export function meditationText(id: string, field: string, lang: string, fallbackES: string, fallbackEN?: string): string {
  const translated = meditationTexts[id + '.' + field]?.[lang];
  if (translated) return translated;
  if (lang !== 'es' && fallbackEN) return fallbackEN;
  return fallbackES;
}

export function getStepText(step: { text: string; textEn?: string }, lang: string): string {
  if (lang === 'es') return step.text;
  return step.textEn || step.text;
}
